void LaneChangeInterface::updateData()
{
  autoware_utils::ScopedTimeTrack st(__func__, *getTimeKeeper());
  module_type_->setPreviousModuleOutput(getPreviousModuleOutput());
  module_type_->update_lanes(getCurrentStatus() == ModuleStatus::RUNNING);
  module_type_->update_filtered_objects();
  module_type_->update_transient_data(getCurrentStatus() == ModuleStatus::RUNNING);
  module_type_->updateSpecialData();

  if (isWaitingApproval() || module_type_->isAbortState()) {
    module_type_->updateLaneChangeStatus();
  }

  module_type_->resetStopPose();
  updateDebugMarker();
}

void setPreviousModuleOutput(const BehaviorModuleOutput & prev_module_output)
{
  prev_module_output_ = prev_module_output;
}

void NormalLaneChange::update_lanes(const bool is_approved)
{
  if (is_approved) {
    return;
  }

  auto current_lanes = utils::getCurrentLanesFromPath(prev_module_output_.path, planner_data_);
  utils::lane_change::trim_preferred_after_alternative(
    current_lanes, common_data_ptr_->route_handler_ptr->getPreferredLanelets());

  if (current_lanes.empty()) {
    return;
  }

  const auto target_lanes = get_lane_change_lanes(current_lanes);
  if (target_lanes.empty()) {
    return;
  }

  lanelet::ConstLanelet current_lane;
  if (!common_data_ptr_->route_handler_ptr->getClosestLaneletWithinRoute(
        common_data_ptr_->get_ego_pose(), &current_lane)) {
    return;
  }

  common_data_ptr_->lanes_ptr->ego_lane = current_lane;
  const auto is_same_lanes_with_prev_iteration =
    utils::lane_change::is_same_lane_with_prev_iteration(
      common_data_ptr_, current_lanes, target_lanes);

  if (is_same_lanes_with_prev_iteration) {
    return;
  }

  common_data_ptr_->lanes_ptr->current = current_lanes;
  common_data_ptr_->lanes_ptr->target = target_lanes;

  const auto & route_handler_ptr = common_data_ptr_->route_handler_ptr;
  common_data_ptr_->current_lanes_path =
    route_handler_ptr->getCenterLinePath(current_lanes, 0.0, std::numeric_limits<double>::max());

  common_data_ptr_->target_lanes_path =
    route_handler_ptr->getCenterLinePath(target_lanes, 0.0, std::numeric_limits<double>::max());

  common_data_ptr_->lanes_ptr->target_neighbor = utils::lane_change::get_target_neighbor_lanes(
    *route_handler_ptr, current_lanes, common_data_ptr_->lc_type);

  common_data_ptr_->current_lanes_path =
    route_handler_ptr->getCenterLinePath(current_lanes, 0.0, std::numeric_limits<double>::max());
  common_data_ptr_->lanes_ptr->current_lane_in_goal_section =
    route_handler_ptr->isInGoalRouteSection(current_lanes.back());
  common_data_ptr_->lanes_ptr->target_lane_in_goal_section =
    route_handler_ptr->isInGoalRouteSection(target_lanes.back());

  common_data_ptr_->lanes_ptr->preceding_target =
    utils::lane_change::get_preceding_lanes(common_data_ptr_);

  lane_change_debug_.current_lanes = common_data_ptr_->lanes_ptr->current;
  lane_change_debug_.target_lanes = common_data_ptr_->lanes_ptr->target;

  lane_change_debug_.target_backward_lanes.clear();
  ranges::for_each(
    common_data_ptr_->lanes_ptr->preceding_target,
    [&](const lanelet::ConstLanelets & preceding_lanes) {
      ranges::insert(
        lane_change_debug_.target_backward_lanes, lane_change_debug_.target_backward_lanes.end(),
        preceding_lanes);
    });

  *common_data_ptr_->lanes_polygon_ptr = create_lanes_polygon(common_data_ptr_);
  common_data_ptr_->no_lane_change_lines =
    utils::lane_change::get_no_lane_change_lines(common_data_ptr_->lanes_ptr->current, direction_);
}

lanelet::ConstLanelets getCurrentLanesFromPath(
  const PathWithLaneId & path, const std::shared_ptr<const PlannerData> & planner_data)
{
  if (path.points.empty() || !planner_data) {
    return {};
  }

  const auto & route_handler = planner_data->route_handler;
  const auto & self_odometry = planner_data->self_odometry;

  if (!route_handler || !self_odometry) {
    return {};
  }

  const auto & current_pose = self_odometry->pose.pose;

  const auto & p = planner_data->parameters;

  std::set<lanelet::Id> lane_ids;
  for (const auto & point : path.points) {
    for (const auto & id : point.lane_ids) {
      lane_ids.insert(id);
    }
  }

  lanelet::ConstLanelets reference_lanes{};
  for (const auto & id : lane_ids) {
    reference_lanes.push_back(planner_data->route_handler->getLaneletsFromId(id));
  }

  const auto current_lane_opt =
    experimental::lanelet2_utils::get_closest_lanelet(reference_lanes, current_pose);
  if (!current_lane_opt) {
    return {};
  }
  const auto & current_lane = current_lane_opt.value();

  auto current_lanes = route_handler->getLaneletSequence(
    current_lane, current_pose, p.backward_path_length, p.forward_path_length);

  // Extend the 'current_lanes' with previous lanes until it contains 'front_lane_ids'
  // if the extended prior lanes is in same lane sequence with current lanes
  const auto front_lane_ids = path.points.front().lane_ids;
  auto have_front_lanes = [front_lane_ids](const auto & lanes) {
    return std::any_of(lanes.begin(), lanes.end(), [&](const auto & lane) {
      return std::find(front_lane_ids.begin(), front_lane_ids.end(), lane.id()) !=
             front_lane_ids.end();
    });
  };

  // if current lanes already have front lanes, return as is
  if (have_front_lanes(current_lanes)) {
    return current_lanes;
  }

  auto extended_lanes = current_lanes;
  while (rclcpp::ok()) {
    const size_t pre_extension_size = extended_lanes.size();  // Get existing size before extension
    extended_lanes = extendPrevLane(route_handler, extended_lanes, true);
    if (extended_lanes.size() == pre_extension_size) break;
    if (have_front_lanes(extended_lanes)) {
      current_lanes = extended_lanes;
      break;
    }
  }

  return current_lanes;
}

std::optional<lanelet::ConstLanelet> get_closest_lanelet(
  const lanelet::ConstLanelets & lanelets, const geometry_msgs::msg::Pose & search_pose)
{
  if (lanelets.empty()) {
    return std::nullopt;
  }

  const lanelet::BasicPoint3d search_point = from_ros(search_pose);

  lanelet::ConstLanelets candidate_lanelets;
  double min_distance = std::numeric_limits<double>::max();
  for (const auto & llt : lanelets) {
    /*
      NOTE(soblin):
      if point is on the edge of, or within the area of that polygon, distance is
      0.0.
      comparable_distance is a distance that maybe be x*x+y*y, not std::hypot of it,
      which is used to only compare distance
      stackoverflow.com/questions/51267577/boost-geometry-polygon-distance-for-inside-point
     */
    const double distance = boost::geometry::comparable_distance(
      llt.polygon2d().basicPolygon(), lanelet::utils::to2D(search_point));

    /*
      NOTE(soblin): this line is intended to push all lanelets on which search_point is located to
      candidate, and later judge by angle
     */
    if (std::fabs(distance - min_distance) <= std::numeric_limits<double>::epsilon()) {
      candidate_lanelets.push_back(llt);
    } else if (distance < min_distance) {
      candidate_lanelets.clear();
      candidate_lanelets.push_back(llt);
      min_distance = distance;
    }
  }

  if (candidate_lanelets.size() == 1) {
    return candidate_lanelets.front();
  }

  // find by angle
  const double pose_yaw = tf2::getYaw(search_pose.orientation);
  double min_angle = std::numeric_limits<double>::max();
  std::optional<lanelet::ConstLanelet> closest_lanelet{};
  for (const auto & llt : candidate_lanelets) {
    const lanelet::ConstLineString3d segment = get_closest_segment(llt.centerline(), search_point);
    if (segment.empty()) {
      continue;
    }
    const auto segment_angle = std::atan2(
      segment.back().y() - segment.front().y(), segment.back().x() - segment.front().x());
    const auto angle_diff =
      std::fabs(autoware_utils_math::normalize_radian(segment_angle - pose_yaw));
    if (angle_diff < min_angle) {
      min_angle = angle_diff;
      closest_lanelet = llt;
    }
  }
  return closest_lanelet;
}

lanelet::ConstPoint3d from_ros(const geometry_msgs::msg::Pose & src)
{
  return from_ros(src.position);
}

lanelet::ConstPoint3d from_ros(const geometry_msgs::msg::Point & src)
{
  return lanelet::ConstPoint3d(lanelet::Point3d(lanelet::InvalId, src.x, src.y, src.z));
}

lanelet::ConstLanelets RouteHandler::getLaneletSequence(
  const lanelet::ConstLanelet & lanelet, const Pose & current_pose, const double backward_distance,
  const double forward_distance) const
{
  if (!exists(route_lanelets_, lanelet)) {
    return {};
  }

  lanelet::ConstLanelets lanelet_sequence_forward =
    getLaneletSequenceAfter(lanelet, forward_distance);
  lanelet::ConstLanelets lanelet_sequence = std::invoke([&]() {
    const auto arc_coordinate =
      autoware::experimental::lanelet2_utils::get_arc_coordinates({lanelet}, current_pose);
    if (arc_coordinate.length < backward_distance) {
      return getLaneletSequenceUpTo(lanelet, backward_distance);
    }
    return lanelet::ConstLanelets{};
  });

  // loop check
  if (!lanelet_sequence_forward.empty() && !lanelet_sequence.empty()) {
    if (lanelet_sequence.back().id() == lanelet_sequence_forward.front().id()) {
      return lanelet_sequence_forward;
    }
  }
  lanelet_sequence.push_back(lanelet);
  std::move(
    lanelet_sequence_forward.begin(), lanelet_sequence_forward.end(),
    std::back_inserter(lanelet_sequence));
  return lanelet_sequence;
}

bool exists(const std::vector<LaneletPrimitive> & primitives, const int64_t & id)
{
  for (const auto & p : primitives) {
    if (p.id == id) {
      return true;
    }
  }
  return false;
}

lanelet::ConstLanelets RouteHandler::getLaneletSequenceAfter(
  const lanelet::ConstLanelet & lanelet, const double min_length) const
{
  lanelet::ConstLanelets lanelet_sequence_forward;
  if (!exists(route_lanelets_, lanelet)) {
    return lanelet_sequence_forward;
  }

  double length = 0;
  lanelet::ConstLanelet current_lanelet = lanelet;
  while (rclcpp::ok() && length < min_length) {
    lanelet::ConstLanelet next_lanelet;
    if (!getNextLaneletWithinRoute(current_lanelet, &next_lanelet)) {
      break;
    }
    // loop check
    if (lanelet.id() == next_lanelet.id()) {
      break;
    }
    lanelet_sequence_forward.push_back(next_lanelet);
    current_lanelet = next_lanelet;
    length +=
      static_cast<double>(boost::geometry::length(next_lanelet.centerline().basicLineString()));
  }

  return lanelet_sequence_forward;
}

bool RouteHandler::getNextLaneletWithinRoute(
  const lanelet::ConstLanelet & lanelet, lanelet::ConstLanelet * next_lanelet) const
{
  lanelet::ConstLanelets next_lanelets{};
  if (getNextLaneletsWithinRoute(lanelet, &next_lanelets)) {
    *next_lanelet = next_lanelets.front();
    return true;
  }
  return false;
}

bool RouteHandler::getNextLaneletsWithinRoute(
  const lanelet::ConstLanelet & lanelet, lanelet::ConstLanelets * next_lanelets) const
{
  if (exists(goal_lanelets_, lanelet)) {
    return false;
  }

  const auto start_lane_id = route_ptr_->segments.front().preferred_primitive.id;

  const auto following_lanelets = routing_graph_ptr_->following(lanelet);
  next_lanelets->clear();
  for (const auto & llt : following_lanelets) {
    if (start_lane_id != llt.id() && exists(route_lanelets_, llt)) {
      next_lanelets->push_back(llt);
    }
  }
  return !(next_lanelets->empty());
}

