bool RouteHandler::getClosestLaneletWithinRoute(
  const Pose & search_pose, lanelet::ConstLanelet * closest_lanelet) const
{
  if (route_lanelets_.empty() || closest_lanelet == nullptr) {
    return false;
  }
  const auto search_point = lanelet::BasicPoint2d(search_pose.position.x, search_pose.position.y);
  const auto query_nearest = boost::geometry::index::nearest(search_point, route_lanelets_.size());
  auto min_dist_to_route_lanelet = std::numeric_limits<double>::max();
  size_t nearest_id = 0;
  // search starting from the nearest bounding box
  for (auto query_it = route_lanelets_rtree_.qbegin(query_nearest);
       query_it != route_lanelets_rtree_.qend(); ++query_it) {
    const auto dist_to_bbox = boost::geometry::comparable_distance(search_point, query_it->first);
    // stop when the distance to the bounding box is larger than the min distance found so far
    if (dist_to_bbox > min_dist_to_route_lanelet) {
      break;
    }
    const auto dist = boost::geometry::comparable_distance(
      search_point, route_lanelets_[query_it->second].polygon2d().basicPolygon());
    if (dist < min_dist_to_route_lanelet) {
      min_dist_to_route_lanelet = dist;
      nearest_id = query_it->second;
    }
  }
  *closest_lanelet = route_lanelets_[nearest_id];
  return true;
}

bool is_same_lane_with_prev_iteration(
  const CommonDataPtr & common_data_ptr, const lanelet::ConstLanelets & current_lanes,
  const lanelet::ConstLanelets & target_lanes)
{
  if (current_lanes.empty() || target_lanes.empty()) {
    return false;
  }
  const auto & prev_current_lanes = common_data_ptr->lanes_ptr->current;
  const auto & prev_target_lanes = common_data_ptr->lanes_ptr->target;
  if (prev_current_lanes.empty() || prev_target_lanes.empty()) {
    return false;
  }

  if (
    (prev_current_lanes.front().id() != current_lanes.front().id()) ||
    (prev_current_lanes.back().id() != prev_current_lanes.back().id())) {
    return false;
  }
  return (prev_target_lanes.front().id() == target_lanes.front().id()) &&
         (prev_target_lanes.back().id() == prev_target_lanes.back().id());
}

PathWithLaneId RouteHandler::getCenterLinePath(
  const lanelet::ConstLanelets & lanelet_sequence, const double s_start, const double s_end,
  bool use_exact) const
{
  using autoware::experimental::lanelet2_utils::create_safe_linestring;
  using autoware::experimental::lanelet2_utils::from_ros;
  using autoware::experimental::lanelet2_utils::interpolate_point;
  using autoware::experimental::lanelet2_utils::to_ros;
  using lanelet::utils::to2D;

  // 1. calculate reference points by lanelets' centerline
  // NOTE: This vector aligns the vector lanelet_sequence.
  std::vector<PiecewiseReferencePoints> piecewise_ref_points_vec;
  for (const auto & llt : lanelet_sequence) {
    const lanelet::ConstLineString3d centerline = llt.centerline();

    piecewise_ref_points_vec.push_back(std::vector<ReferencePoint>{});
    for (const auto & center_point : centerline) {
      piecewise_ref_points_vec.back().push_back(
        ReferencePoint{false, experimental::lanelet2_utils::to_ros(center_point)});
    }
  }

  // 2. calculate waypoints
  const auto waypoints_vec = calcWaypointsVector(lanelet_sequence);

  // 3. remove points in the margin of the waypoint
  for (const auto & waypoints : waypoints_vec) {
    for (auto piecewise_waypoints_itr = waypoints.begin();
         piecewise_waypoints_itr != waypoints.end(); ++piecewise_waypoints_itr) {
      const auto & piecewise_waypoints = piecewise_waypoints_itr->piecewise_waypoints;
      const auto lanelet_id = piecewise_waypoints_itr->lanelet_id;

      // calculate index of lanelet_sequence which corresponds to piecewise_waypoints.
      const auto lanelet_sequence_itr = std::find_if(
        lanelet_sequence.begin(), lanelet_sequence.end(),
        [&](const auto & lanelet) { return lanelet.id() == lanelet_id; });
      if (lanelet_sequence_itr == lanelet_sequence.end()) {
        continue;
      }
      const size_t piecewise_waypoints_lanelet_sequence_index =
        std::distance(lanelet_sequence.begin(), lanelet_sequence_itr);

      // calculate reference points by waypoints
      const auto ref_points_by_waypoints = convertWaypointsToReferencePoints(piecewise_waypoints);

      // update reference points by waypoints
      const bool is_first_waypoint_contained = piecewise_waypoints_itr == waypoints.begin();
      const bool is_last_waypoint_contained = piecewise_waypoints_itr == waypoints.end() - 1;
      if (is_first_waypoint_contained || is_last_waypoint_contained) {
        // If piecewise_waypoints_itr is the end (first or last) of piecewise_waypoints

        const auto original_piecewise_ref_points =
          piecewise_ref_points_vec.at(piecewise_waypoints_lanelet_sequence_index);

        // define current_piecewise_ref_points, and initialize it with waypoints
        auto & current_piecewise_ref_points =
          piecewise_ref_points_vec.at(piecewise_waypoints_lanelet_sequence_index);
        current_piecewise_ref_points = ref_points_by_waypoints;
        if (is_first_waypoint_contained) {
          // add original reference points to current reference points, and remove reference points
          // overlapped with waypoints
          current_piecewise_ref_points.insert(
            current_piecewise_ref_points.begin(), original_piecewise_ref_points.begin(),
            original_piecewise_ref_points.end());
          const bool is_removing_direction_forward = false;
          removeOverlappedCenterlineWithWaypoints(
            piecewise_ref_points_vec, piecewise_waypoints, lanelet_sequence,
            piecewise_waypoints_lanelet_sequence_index, is_removing_direction_forward);
        }
        if (is_last_waypoint_contained) {
          // add original reference points to current reference points, and remove reference points
          // overlapped with waypoints
          current_piecewise_ref_points.insert(
            current_piecewise_ref_points.end(), original_piecewise_ref_points.begin(),
            original_piecewise_ref_points.end());
          const bool is_removing_direction_forward = true;
          removeOverlappedCenterlineWithWaypoints(
            piecewise_ref_points_vec, piecewise_waypoints, lanelet_sequence,
            piecewise_waypoints_lanelet_sequence_index, is_removing_direction_forward);
        }
      } else {
        // If piecewise_waypoints_itr is not the end (first or last) of piecewise_waypoints,
        // remove all the reference points and add waypoints.
        piecewise_ref_points_vec.at(piecewise_waypoints_lanelet_sequence_index) =
          ref_points_by_waypoints;
      }
    }
  }

  PathWithLaneId reference_path{};
  const auto add_path_point =
    [&](const auto & point, const auto & lanelet, const auto & speed_limit) {
      PathPointWithLaneId p{};
      p.point.pose.position = point;
      p.lane_ids.push_back(lanelet.id());
      p.point.longitudinal_velocity_mps = speed_limit;
      reference_path.points.push_back(p);
    };

  // 4. convert to PathPointsWithLaneIds with cropping
  double s = 0.0;
  for (size_t lanelet_idx = 0; lanelet_idx < lanelet_sequence.size(); ++lanelet_idx) {
    const auto & lanelet = lanelet_sequence.at(lanelet_idx);
    const float speed_limit =
      static_cast<float>(traffic_rules_ptr_->speedLimit(lanelet).speedLimit.value());

    const auto & piecewise_ref_points = piecewise_ref_points_vec.at(lanelet_idx);
    for (size_t ref_point_idx = 0; ref_point_idx < piecewise_ref_points.size(); ++ref_point_idx) {
      const auto & ref_point = piecewise_ref_points.at(ref_point_idx);
      const auto & next_ref_point = (ref_point_idx + 1 < piecewise_ref_points.size())
                                      ? piecewise_ref_points.at(ref_point_idx + 1)
                                    : (lanelet_idx + 1 < lanelet_sequence.size())
                                      ? piecewise_ref_points_vec.at(lanelet_idx + 1).at(0)
                                      : piecewise_ref_points.at(ref_point_idx);

      const double distance =
        autoware_utils_geometry::calc_distance2d(ref_point.point, next_ref_point.point);

      if (s < s_start && s + distance > s_start) {
        const auto p_opt = getGeometryPointFrom2DArcLength(lanelet_sequence, s_start);
        if (p_opt.has_value()) {
          // convert geometry_msgs to ros_msg
          const auto ref_pt = from_ros(ref_point.point);
          const auto next_pt = from_ros(next_ref_point.point);
          const auto on_centerline_pt = to2D(from_ros(p_opt.value())).basicPoint();

          lanelet::ConstPoints3d segment{ref_pt, next_pt};
          const auto ls_opt = create_safe_linestring(segment);
          geometry_msgs::msg::Point p = ref_point.point;
          // find interpolated point on "waypoint" if there is.
          if (use_exact && ls_opt.has_value()) {
            const auto ls = to2D(*ls_opt);

            const auto arc_coord = lanelet::geometry::toArcCoordinates(ls, on_centerline_pt);
            const auto interpolated_pt_opt = interpolate_point(ref_pt, next_pt, arc_coord.length);
            p = interpolated_pt_opt.has_value() ? to_ros(interpolated_pt_opt.value())
                                                : ref_point.point;
          }
          add_path_point(p, lanelet, speed_limit);
        } else {
          add_path_point(ref_point.point, lanelet, speed_limit);
        }
      }
      if (s >= s_start && s <= s_end) {
        add_path_point(ref_point.point, lanelet, speed_limit);
      }
      if (s < s_end && s + distance > s_end) {
        const auto p_opt = getGeometryPointFrom2DArcLength(lanelet_sequence, s_end);
        if (p_opt.has_value()) {
          const auto p = use_exact ? p_opt.value() : ref_point.point;
          add_path_point(p, lanelet, speed_limit);
        } else {
          add_path_point(ref_point.point, lanelet, speed_limit);
        }
      }
      s += distance;
    }
  }
  reference_path = removeOverlappingPoints(reference_path);

  // append a point only when having one point so that yaw calculation would work
  if (reference_path.points.size() == 1) {
    const lanelet::Id lane_id = reference_path.points.front().lane_ids.front();
    const auto lanelet = lanelet_map_ptr_->laneletLayer.get(lane_id);
    const auto point = reference_path.points.front().point.pose.position;
    const auto lane_yaw = autoware::experimental::lanelet2_utils::get_lanelet_angle(
      lanelet, autoware::experimental::lanelet2_utils::from_ros(point).basicPoint());
    PathPointWithLaneId path_point{};
    path_point.lane_ids.push_back(lane_id);
    constexpr double ds{0.1};
    path_point.point.pose.position.x = point.x + ds * std::cos(lane_yaw);
    path_point.point.pose.position.y = point.y + ds * std::sin(lane_yaw);
    path_point.point.pose.position.z = point.z;
    reference_path.points.push_back(path_point);
  }

  // set angle
  for (size_t i = 0; i < reference_path.points.size(); i++) {
    double angle{0.0};
    const auto & pts = reference_path.points;
    if (i + 1 < reference_path.points.size()) {
      angle = autoware_utils_geometry::calc_azimuth_angle(
        pts.at(i).point.pose.position, pts.at(i + 1).point.pose.position);
    } else if (i != 0) {
      angle = autoware_utils_geometry::calc_azimuth_angle(
        pts.at(i - 1).point.pose.position, pts.at(i).point.pose.position);
    }
    reference_path.points.at(i).point.pose.orientation =
      autoware_utils_geometry::create_quaternion_from_yaw(angle);
  }

  return reference_path;
}

void NormalLaneChange::update_filtered_objects()
{
  filtered_objects_ = filter_objects();
}

FilteredLanesObjects NormalLaneChange::filter_objects() const
{
  autoware_utils::ScopedTimeTrack st(__func__, *time_keeper_);
  auto objects = *planner_data_->dynamic_object;
  utils::path_safety_checker::filterObjectsByClass(
    objects, lane_change_parameters_->safety.target_object_types);

  if (objects.objects.empty()) {
    return {};
  }

  filterOncomingObjects(objects);

  if (objects.objects.empty()) {
    return {};
  }

  if (!common_data_ptr_->is_lanes_available()) {
    return {};
  }

  const auto & current_pose = common_data_ptr_->get_ego_pose();
  const auto & current_lanes = common_data_ptr_->lanes_ptr->current;

  const auto & current_lanes_ref_path = common_data_ptr_->current_lanes_path;

  const auto & lanes_polygon = *common_data_ptr_->lanes_polygon_ptr;
  const auto dist_ego_to_current_lanes_center =
    autoware::experimental::lanelet2_utils::get_lateral_distance_to_centerline(
      current_lanes, current_pose);

  FilteredLanesObjects filtered_objects;
  const auto reserve_size = objects.objects.size();
  filtered_objects.current_lane.reserve(reserve_size);
  auto & target_lane_leading = filtered_objects.target_lane_leading;
  target_lane_leading.stopped.reserve(reserve_size);
  target_lane_leading.moving.reserve(reserve_size);
  target_lane_leading.stopped_at_bound.reserve(reserve_size);
  filtered_objects.target_lane_trailing.reserve(reserve_size);
  filtered_objects.others.reserve(reserve_size);

  for (const auto & object : objects.objects) {
    auto ext_object = utils::lane_change::transform(object, *lane_change_parameters_);
    const auto & ext_obj_pose = ext_object.initial_pose;
    ext_object.dist_from_ego = autoware::motion_utils::calcSignedArcLength(
      current_lanes_ref_path.points, current_pose.position, ext_obj_pose.position);

    const auto is_before_terminal =
      utils::lane_change::is_before_terminal(common_data_ptr_, current_lanes_ref_path, ext_object);

    const auto ego_object_proximity = utils::lane_change::calc_ego_object_proximity(
      common_data_ptr_, current_lanes_ref_path, ext_object);

    const auto ahead_of_ego = ego_object_proximity.is_ahead_of_ego;

    if (utils::lane_change::filter_target_lane_objects(
          common_data_ptr_, ext_object, dist_ego_to_current_lanes_center, ego_object_proximity,
          is_before_terminal, target_lane_leading, filtered_objects.target_lane_trailing)) {
      continue;
    }

    if (
      ahead_of_ego && is_before_terminal &&
      !boost::geometry::disjoint(ext_object.initial_polygon, lanes_polygon.current)) {
      // check only the objects that are in front of the ego vehicle
      filtered_objects.current_lane.push_back(ext_object);
      continue;
    }

    filtered_objects.others.push_back(ext_object);
  }

  const auto dist_comparator = [](const auto & obj1, const auto & obj2) {
    return obj1.dist_from_ego < obj2.dist_from_ego;
  };

  // There are no use cases for other lane objects yet, so to save some computation time, we dont
  // have to sort them.
  ranges::sort(filtered_objects.current_lane, dist_comparator);
  ranges::sort(target_lane_leading.stopped_at_bound, dist_comparator);
  ranges::sort(target_lane_leading.stopped, dist_comparator);
  ranges::sort(target_lane_leading.moving, dist_comparator);
  ranges::sort(filtered_objects.target_lane_trailing, [](const auto & obj1, const auto & obj2) {
    return obj2.dist_from_ego < obj1.dist_from_ego;
  });

  lane_change_debug_.filtered_objects = filtered_objects;

  return filtered_objects;
}

void filterObjectsByClass(
  PredictedObjects & objects, const ObjectTypesToCheck & target_object_types)
{
  const auto filter = [&](const auto & object) {
    return isTargetObjectType(object, target_object_types);
  };

  filterObjects(objects, filter);
}

bool isTargetObjectType(
  const PredictedObject & object, const ObjectTypesToCheck & target_object_types)
{
  using autoware_perception_msgs::msg::ObjectClassification;
  const auto t = utils::getHighestProbLabel(object.classification);
  return (
    (t == ObjectClassification::CAR && target_object_types.check_car) ||
    (t == ObjectClassification::TRUCK && target_object_types.check_truck) ||
    (t == ObjectClassification::BUS && target_object_types.check_bus) ||
    (t == ObjectClassification::TRAILER && target_object_types.check_trailer) ||
    (t == ObjectClassification::UNKNOWN && target_object_types.check_unknown) ||
    (t == ObjectClassification::BICYCLE && target_object_types.check_bicycle) ||
    (t == ObjectClassification::MOTORCYCLE && target_object_types.check_motorcycle) ||
    (t == ObjectClassification::PEDESTRIAN && target_object_types.check_pedestrian));
}

std::uint8_t getHighestProbLabel(const std::vector<ObjectClassification> & classification)
{
  std::uint8_t label = ObjectClassification::UNKNOWN;
  float highest_prob = 0.0;
  for (const auto & _class : classification) {
    if (highest_prob < _class.probability) {
      highest_prob = _class.probability;
      label = _class.label;
    }
  }
  return label;
}

PredictedObjects filterObjects(
  const std::shared_ptr<const PredictedObjects> & objects,
  const std::shared_ptr<RouteHandler> & route_handler, const lanelet::ConstLanelets & current_lanes,
  const geometry_msgs::msg::Point & current_pose,
  const std::shared_ptr<ObjectsFilteringParams> & params)
{
  // Guard
  if (objects->objects.empty() || !params) {
    return PredictedObjects();
  }

  const double ignore_object_velocity_threshold = params->ignore_object_velocity_threshold;
  const double object_check_forward_distance = params->object_check_forward_distance;
  const double object_check_backward_distance = params->object_check_backward_distance;
  const ObjectTypesToCheck & target_object_types = params->object_types_to_check;

  PredictedObjects filtered_objects =
    filterObjectsByVelocity(*objects, ignore_object_velocity_threshold, true);

  filterObjectsByClass(filtered_objects, target_object_types);

  const auto path = route_handler->getCenterLinePath(
    current_lanes, object_check_backward_distance, object_check_forward_distance);

  filterObjectsByPosition(
    filtered_objects, path.points, current_pose, object_check_forward_distance,
    object_check_backward_distance);

  return filtered_objects;
}

PredictedObjects filterObjectsByVelocity(
  const PredictedObjects & objects, const double velocity_threshold,
  const bool remove_above_threshold)
{
  if (!remove_above_threshold) {
    return filterObjectsByVelocity(objects, -velocity_threshold, velocity_threshold);
  }
  return filterObjectsByVelocity(objects, velocity_threshold, std::numeric_limits<double>::max());
}

PredictedObjects filterObjectsByVelocity( //
  const PredictedObjects & objects, double velocity_threshold, double max_velocity)
{
  const auto filter = [&](const auto & object) {
    return filter::velocity_filter(
      object.kinematics.initial_twist_with_covariance.twist, velocity_threshold, max_velocity);
  };

  auto filtered = objects;
  filterObjects(filtered, filter);
  return filtered;
}

