  const lanelet::ConstLanelet & lanelet, const geometry_msgs::msg::Point & point)
{
  return lanelet::geometry::toArcCoordinates(
    to2D(lanelet.centerline()), to2D(experimental::lanelet2_utils::from_ros(point)).basicPoint());
}

