PathWithLaneId removeOverlappingPoints(const PathWithLaneId & input_path)
{
  PathWithLaneId filtered_path;
  filtered_path.points.reserve(input_path.points.size());

  double previous_azimuth = 0;

  for (const auto & pt : input_path.points) {
    if (filtered_path.points.empty()) {
      filtered_path.points.push_back(pt);
      continue;
    }

    constexpr double th_overlapping_dist = 0.001;
    constexpr double th_overlapping_dist_discontinuity = 0.05;
    const double dist_between_points =
      autoware_utils_geometry::calc_distance3d(filtered_path.points.back().point, pt.point);

    const double current_azimuth = autoware_utils_geometry::calc_azimuth_angle(
      filtered_path.points.back().point.pose.position, pt.point.pose.position);

    if (dist_between_points < th_overlapping_dist) {
      filtered_path.points.back().lane_ids.push_back(pt.lane_ids.front());
      filtered_path.points.back().point.longitudinal_velocity_mps =
        pt.point.longitudinal_velocity_mps;
      continue;
    }

    // If the direction changes sharply (not smooth) but the points are very close,
    // treat it as an overlap.
    // This can occur at joints between a waypoint and an auto-generated centerline.
    // It's not considered overlap in ordinary case, thus, this case relax the condition.
    if (
      (std::fabs(autoware_utils_math::normalize_radian(previous_azimuth - current_azimuth)) >=
       M_PI / 2) &&
      (dist_between_points < th_overlapping_dist_discontinuity)) {
      filtered_path.points.back().lane_ids.push_back(pt.lane_ids.front());
      filtered_path.points.back().point.longitudinal_velocity_mps =
        pt.point.longitudinal_velocity_mps;
      continue;
    }

    filtered_path.points.push_back(pt);
    previous_azimuth = current_azimuth;
  }

  filtered_path.left_bound = input_path.left_bound;
  filtered_path.right_bound = input_path.right_bound;
  return filtered_path;
}

double calc_distance3d(const Point1 & point1, const Point2 & point2)
{
  const auto p1 = get_point(point1);
  const auto p2 = get_point(point2);
  // To be replaced by std::hypot(dx, dy, dz) in C++17
  return std::hypot(std::hypot(p1.x - p2.x, p1.y - p2.y), p1.z - p2.z);
}

geometry_msgs::msg::Point get_point(const T & p)
{
  return geometry_msgs::build<geometry_msgs::msg::Point>().x(p.x).y(p.y).z(p.z);
}

double calc_azimuth_angle(
  const geometry_msgs::msg::Point & p_from, const geometry_msgs::msg::Point & p_to)
{
  const double dx = p_to.x - p_from.x;
  const double dy = p_to.y - p_from.y;
  return std::atan2(dy, dx);
}

inline double normalize_radian(const double rad, const double min_rad = -pi)
{
  const auto max_rad = min_rad + 2 * pi;

  const auto value = std::fmod(rad, 2 * pi);
  if (min_rad <= value && value < max_rad) {
    return value;
  }

  return value - std::copysign(2 * pi, value);
}

void filterObjectsByPosition(
  PredictedObjects & objects, const std::vector<PathPointWithLaneId> & path_points,
  const geometry_msgs::msg::Point & current_pose, const double forward_distance,
  const double backward_distance)
{
  const auto filter = [&](const auto & object) {
    return filter::position_filter(
      object, path_points, current_pose, forward_distance, -backward_distance);
  };

  filterObjects(objects, filter);
}

void filterObjects(PredictedObjects & selected, PredictedObjects & removed, Func filter)
{
  auto partitioned = std::partition(selected.objects.begin(), selected.objects.end(), filter);
  removed.objects.insert(removed.objects.end(), partitioned, selected.objects.end());
  selected.objects.erase(partitioned, selected.objects.end());
}

ExtendedPredictedObject transform(
  const PredictedObject & object, const LaneChangeParameters & lane_change_parameters)
{
  ExtendedPredictedObject extended_object(object);

  const auto & time_resolution =
    lane_change_parameters.safety.collision_check.prediction_time_resolution;
  const double obj_vel_norm =
    std::hypot(extended_object.initial_twist.linear.x, extended_object.initial_twist.linear.y);

  const auto object_predicted_paths = path_safety_checker::get_object_predicted_paths(
    object.kinematics.predicted_paths,
    lane_change_parameters.safety.collision_check.use_all_predicted_paths);

  extended_object.predicted_paths.reserve(object.kinematics.predicted_paths.size());

  for (const auto & pred_path : object_predicted_paths) {
    if (
      const auto ext_path_opt =
        transform_predicted_path(pred_path, object.shape, obj_vel_norm, time_resolution)) {
      extended_object.predicted_paths.push_back(*ext_path_opt);
    }
  }

  return extended_object;
}

PredictedPathsType get_object_predicted_paths(
  const PredictedPathsType & predicted_paths, const bool is_use_all_predicted_path)
{
  return is_use_all_predicted_path ? predicted_paths
                                   : get_highest_confidence_paths(predicted_paths);
}

PredictedPathsType get_highest_confidence_paths(PredictedPathsType predicted_paths)
{
  if (predicted_paths.empty()) {
    return predicted_paths;
  }

  std::sort(predicted_paths.begin(), predicted_paths.end(), [](const auto & p1, const auto & p2) {
    return p1.confidence > p2.confidence;
  });

  const auto highest_confidence = predicted_paths.front().confidence;

  // handles if the multiple path have the same highest confidence
  auto equal_confidence_itr = std::find_if(
    std::next(predicted_paths.begin()), predicted_paths.end(),
    [highest_confidence](const auto & p) { return p.confidence != highest_confidence; });

  return {predicted_paths.begin(), equal_confidence_itr};
}

std::optional<PredictedPathWithPolygon> transform_predicted_path(
  const autoware_perception_msgs::msg::PredictedPath & path,
  const autoware_perception_msgs::msg::Shape & obj_shape, const double obj_normal_velocity,
  const double time_resolution)
{
  if (path.path.empty()) {
    return std::nullopt;
  }
  PredictedPathWithPolygon pred_path_with_poly;
  pred_path_with_poly.confidence = path.confidence;

  const auto end_time =
    rclcpp::Duration(path.time_step).seconds() * static_cast<double>(path.path.size() - 1);
  constexpr auto eps = std::numeric_limits<double>::epsilon();
  const auto num_iterations = static_cast<size_t>(std::ceil(end_time / time_resolution)) + 1;
  pred_path_with_poly.path.reserve(num_iterations);

  for (double t = 0.0; t < end_time + eps; t += time_resolution) {
    if (
      const auto obj_pose_opt = autoware::object_recognition_utils::calcInterpolatedPose(path, t)) {
      const auto obj_polygon = autoware_utils::to_polygon2d(*obj_pose_opt, obj_shape);
      pred_path_with_poly.path.emplace_back(t, *obj_pose_opt, obj_normal_velocity, obj_polygon);
    }
  }

  if (pred_path_with_poly.path.empty()) {
    return std::nullopt;
  }

  return pred_path_with_poly;
}

boost::optional<geometry_msgs::msg::Pose> calcInterpolatedPose(
  const autoware_perception_msgs::msg::PredictedPath & path, const double relative_time)
{
  // Check if relative time is in the valid range
  if (path.path.empty() || relative_time < 0.0) {
    return boost::none;
  }

  constexpr double epsilon = 1e-6;
  const double & time_step = rclcpp::Duration(path.time_step).seconds();
  for (size_t path_idx = 1; path_idx < path.path.size(); ++path_idx) {
    const auto & pt = path.path.at(path_idx);
    const auto & prev_pt = path.path.at(path_idx - 1);
    if (relative_time - epsilon < time_step * static_cast<double>(path_idx)) {
      const double offset = relative_time - time_step * static_cast<double>(path_idx - 1);
      const double ratio = std::clamp(offset / time_step, 0.0, 1.0);
      return autoware_utils_geometry::calc_interpolated_pose(prev_pt, pt, ratio, false);
    }
  }

  return boost::none;
}

geometry_msgs::msg::Pose calc_interpolated_pose(
  const Pose1 & src_pose, const Pose2 & dst_pose, const double ratio,
  const bool set_orientation_from_position_direction = true)
{
  const double clamped_ratio = std::clamp(ratio, 0.0, 1.0);

  geometry_msgs::msg::Pose output_pose;
  output_pose.position =
    calc_interpolated_point(get_point(src_pose), get_point(dst_pose), clamped_ratio);

  if (set_orientation_from_position_direction) {
    const double input_poses_dist = calc_distance2d(get_point(src_pose), get_point(dst_pose));
    const bool is_driving_forward_flag = is_driving_forward(src_pose, dst_pose);

    // Get orientation from interpolated point and src_pose
    if ((is_driving_forward_flag && clamped_ratio > 1.0 - (1e-6)) || input_poses_dist < 1e-3) {
      output_pose.orientation = get_pose(dst_pose).orientation;
    } else if (!is_driving_forward_flag && clamped_ratio < 1e-6) {
      output_pose.orientation = get_pose(src_pose).orientation;
    } else {
      const auto & base_pose = is_driving_forward_flag ? dst_pose : src_pose;
      const double pitch = calc_elevation_angle(get_point(output_pose), get_point(base_pose));
      const double yaw = calc_azimuth_angle(get_point(output_pose), get_point(base_pose));
      output_pose.orientation = create_quaternion_from_rpy(0.0, pitch, yaw);
    }
  } else {
    // Get orientation by spherical linear interpolation
    tf2::Transform src_tf;
    tf2::Transform dst_tf;
    tf2::fromMsg(get_pose(src_pose), src_tf);
    tf2::fromMsg(get_pose(dst_pose), dst_tf);
    const auto & quaternion = tf2::slerp(src_tf.getRotation(), dst_tf.getRotation(), clamped_ratio);
    output_pose.orientation = tf2::toMsg(quaternion);
  }

  return output_pose;
}

geometry_msgs::msg::Point calc_interpolated_point(
  const Point1 & src, const Point2 & dst, const double ratio)
{
  const auto src_point = get_point(src);
  const auto dst_point = get_point(dst);

  tf2::Vector3 src_vec;
  src_vec.setX(src_point.x);
  src_vec.setY(src_point.y);
  src_vec.setZ(src_point.z);

  tf2::Vector3 dst_vec;
  dst_vec.setX(dst_point.x);
  dst_vec.setY(dst_point.y);
  dst_vec.setZ(dst_point.z);

  // Get pose by linear interpolation
  const double clamped_ratio = std::clamp(ratio, 0.0, 1.0);
  const auto & vec = tf2::lerp(src_vec, dst_vec, clamped_ratio);

  geometry_msgs::msg::Point point;
  point.x = vec.x();
  point.y = vec.y();
  point.z = vec.z();

  return point;
}

