bool filter_target_lane_objects(
  const CommonDataPtr & common_data_ptr, const ExtendedPredictedObject & object,
  const double dist_ego_to_current_lanes_center, const EgoObjectProximity & ego_object_proximity,
  const bool before_terminal, TargetLaneLeadingObjects & leading_objects,
  ExtendedPredictedObjects & trailing_objects)
{
  using behavior_path_planner::utils::path_safety_checker::filter::is_vehicle;
  using behavior_path_planner::utils::path_safety_checker::filter::velocity_filter;
  const auto & current_lanes = common_data_ptr->lanes_ptr->current;
  const auto & vehicle_width = common_data_ptr->bpp_param_ptr->vehicle_info.vehicle_width_m;
  const auto & lanes_polygon = *common_data_ptr->lanes_polygon_ptr;
  const auto stopped_obj_vel_th = common_data_ptr->lc_param_ptr->safety.th_stopped_object_velocity;

  const auto is_lateral_far = std::invoke([&]() -> bool {
    const auto dist_object_to_current_lanes_center =
      autoware::experimental::lanelet2_utils::get_lateral_distance_to_centerline(
        current_lanes, object.initial_pose);
    const auto lateral = dist_object_to_current_lanes_center - dist_ego_to_current_lanes_center;
    return std::abs(lateral) > (vehicle_width / 2);
  });

  const auto ahead_of_ego = ego_object_proximity.is_ahead_of_ego;

  const auto is_stopped = velocity_filter(
    object.initial_twist, -std::numeric_limits<double>::epsilon(), stopped_obj_vel_th);
  if (is_lateral_far && before_terminal) {
    const auto overlapping_with_target_lanes =
      !boost::geometry::disjoint(object.initial_polygon, lanes_polygon.target) ||
      (!is_stopped && is_vehicle(object.classification) &&
       object_path_overlaps_lanes(object, lanes_polygon.target));

    if (overlapping_with_target_lanes) {
      if ((!ahead_of_ego && !is_stopped) || ego_object_proximity.is_overlapping()) {
        trailing_objects.push_back(object);
        return true;
      }

      if (ahead_of_ego) {
        if (is_stopped) {
          leading_objects.stopped.push_back(object);
        } else {
          leading_objects.moving.push_back(object);
        }
        return true;
      }
    }

    // Check if the object is positioned outside the lane boundary but still close to its edge.
    const auto in_expanded_target_lanes =
      !boost::geometry::disjoint(object.initial_polygon, lanes_polygon.expanded_target);

    if (in_expanded_target_lanes && is_stopped && ahead_of_ego) {
      leading_objects.stopped_at_bound.push_back(object);
      return true;
    }
  }

  const auto is_overlap_target_backward =
    ranges::any_of(lanes_polygon.preceding_target, [&](const auto & target_backward_polygon) {
      return !boost::geometry::disjoint(object.initial_polygon, target_backward_polygon);
    });

  // check if the object intersects with target backward lanes
  if (is_overlap_target_backward && !is_stopped) {
    trailing_objects.push_back(object);
    return true;
  }

  return false;
}

double get_lateral_distance_to_centerline(
  const lanelet::ConstLanelets & lanelet_sequence, const geometry_msgs::msg::Pose & pose)
{
  const auto closest_lanelet_opt = get_closest_lanelet(lanelet_sequence, pose);
  if (!closest_lanelet_opt.has_value()) {
    RCLCPP_ERROR(
      rclcpp::get_logger("autoware_lanelet2_utility"),
      "Failed to find closest lanelet. Returning 0.0 lateral distance.");
    return 0.0;
  }

  return get_lateral_distance_to_centerline(*closest_lanelet_opt, pose);
}

std::optional<lanelet::ConstLanelet> get_closest_lanelet(
  const lanelet::ConstLanelets & lanelets, const geometry_msgs::msg::Pose & search_pose)
{
  if (lanelets.empty()) {
    return std::nullopt;
  }

  const lanelet::BasicPoint3d search_point = from_ros(search_pose);

  lanelet::ConstLanelets candidate_lanelets;
  double min_distance = std::numeric_limits<double>::max();
  for (const auto & llt : lanelets) {
    /*
      NOTE(soblin):
      if point is on the edge of, or within the area of that polygon, distance is
      0.0.
      comparable_distance is a distance that maybe be x*x+y*y, not std::hypot of it,
      which is used to only compare distance
      stackoverflow.com/questions/51267577/boost-geometry-polygon-distance-for-inside-point
     */
    const double distance = boost::geometry::comparable_distance(
      llt.polygon2d().basicPolygon(), lanelet::utils::to2D(search_point));

    /*
      NOTE(soblin): this line is intended to push all lanelets on which search_point is located to
      candidate, and later judge by angle
     */
    if (std::fabs(distance - min_distance) <= std::numeric_limits<double>::epsilon()) {
      candidate_lanelets.push_back(llt);
    } else if (distance < min_distance) {
      candidate_lanelets.clear();
      candidate_lanelets.push_back(llt);
      min_distance = distance;
    }
  }

  if (candidate_lanelets.size() == 1) {
    return candidate_lanelets.front();
  }

  // find by angle
  const double pose_yaw = tf2::getYaw(search_pose.orientation);
  double min_angle = std::numeric_limits<double>::max();
  std::optional<lanelet::ConstLanelet> closest_lanelet{};
  for (const auto & llt : candidate_lanelets) {
    const lanelet::ConstLineString3d segment = get_closest_segment(llt.centerline(), search_point);
    if (segment.empty()) {
      continue;
    }
    const auto segment_angle = std::atan2(
      segment.back().y() - segment.front().y(), segment.back().x() - segment.front().x());
    const auto angle_diff =
      std::fabs(autoware_utils_math::normalize_radian(segment_angle - pose_yaw));
    if (angle_diff < min_angle) {
      min_angle = angle_diff;
      closest_lanelet = llt;
    }
  }
  return closest_lanelet;
}

lanelet::ConstLineString3d get_closest_segment(
  const lanelet::ConstLineString3d & linestring, const lanelet::BasicPoint3d & search_pt)
{
  lanelet::ConstLineString3d closest_segment;
  double min_distance = std::numeric_limits<double>::max();

  for (const auto & [prev_pt, current_pt] :
       ranges::views::zip(linestring, linestring | ranges::views::drop(1))) {
    lanelet::Point3d prev_pt_3d(lanelet::InvalId, prev_pt.x(), prev_pt.y(), prev_pt.z());
    lanelet::Point3d current_pt_3d(
      lanelet::InvalId, current_pt.x(), current_pt.y(), current_pt.z());

    lanelet::ConstLineString3d current_segment(lanelet::InvalId, {prev_pt_3d, current_pt_3d});
    double distance = lanelet::geometry::distance3d(current_segment.basicLineString(), search_pt);
    if (distance < min_distance) {
      closest_segment = current_segment;
      min_distance = distance;
    }
  }
  return closest_segment;
}

inline double normalize_radian(const double rad, const double min_rad = -pi)
{
  const auto max_rad = min_rad + 2 * pi;

  const auto value = std::fmod(rad, 2 * pi);
  if (min_rad <= value && value < max_rad) {
    return value;
  }

  return value - std::copysign(2 * pi, value);
}

double get_lateral_distance_to_centerline(
  const lanelet::ConstLanelet & lanelet, const geometry_msgs::msg::Pose & pose)
{
  const auto & centerline_2d = lanelet::utils::to2D(lanelet.centerline());
  const auto lanelet_point = from_ros(pose);
  return lanelet::geometry::signedDistance(
    centerline_2d, lanelet::utils::to2D(lanelet_point).basicPoint());
}

bool object_path_overlaps_lanes(
  const ExtendedPredictedObject & object, const lanelet::BasicPolygon2d & lanes_polygon)
{
  return ranges::any_of(get_line_string_paths(object), [&](const auto & path) {
    return !boost::geometry::disjoint(path, lanes_polygon);
  });
}

std::vector<LineString2d> get_line_string_paths(const ExtendedPredictedObject & object)
{
  const auto to_linestring_2d = [](const auto & predicted_path) -> LineString2d {
    LineString2d line_string;
    const auto & path = predicted_path.path;
    line_string.reserve(path.size());
    for (const auto & path_point : path) {
      const auto point = autoware_utils::from_msg(path_point.pose.position).to_2d();
      line_string.push_back(point);
    }

    return line_string;
  };

  return object.predicted_paths | ranges::views::transform(to_linestring_2d) |
         ranges::to<std::vector>();
}

void NormalLaneChange::update_transient_data(const bool is_approved)
{
  if (
    !common_data_ptr_ || !common_data_ptr_->is_data_available() ||
    !common_data_ptr_->is_lanes_available()) {
    return;
  }

  auto & transient_data = common_data_ptr_->transient_data;

  const auto & p = *common_data_ptr_->bpp_param_ptr;
  const auto nearest_seg_idx =
    autoware::motion_utils::findFirstNearestSegmentIndexWithSoftConstraints(
      prev_module_output_.path.points, common_data_ptr_->get_ego_pose(),
      p.ego_nearest_dist_threshold, p.ego_nearest_yaw_threshold);
  transient_data.current_path_velocity =
    prev_module_output_.path.points.at(nearest_seg_idx).point.longitudinal_velocity_mps;
  transient_data.current_path_seg_idx = nearest_seg_idx;

  const auto active_signal_duration =
    signal_activation_time_ ? (clock_.now() - signal_activation_time_.value()).seconds() : 0.0;
  transient_data.lane_change_prepare_duration =
    is_approved ? status_.lane_change_path.info.duration.prepare
                : calculation::calc_actual_prepare_duration(
                    common_data_ptr_, common_data_ptr_->get_ego_speed(), active_signal_duration);

  std::tie(transient_data.lane_changing_length, transient_data.current_dist_buffer) =
    calculation::calc_lc_length_and_dist_buffer(common_data_ptr_, get_current_lanes());

  transient_data.next_dist_buffer.min =
    transient_data.current_dist_buffer.min - transient_data.lane_changing_length.min -
    common_data_ptr_->lc_param_ptr->lane_change_finish_judge_buffer;

  transient_data.dist_to_terminal_end = calculation::calc_dist_from_pose_to_terminal_end(
    common_data_ptr_, common_data_ptr_->lanes_ptr->current, common_data_ptr_->get_ego_pose());
  transient_data.dist_to_terminal_start =
    transient_data.dist_to_terminal_end - transient_data.current_dist_buffer.min;

  transient_data.dist_to_target_end = calculation::calc_dist_from_pose_to_terminal_end(
    common_data_ptr_, common_data_ptr_->lanes_ptr->target, common_data_ptr_->get_ego_pose());

  transient_data.max_prepare_length = calculation::calc_maximum_prepare_length(common_data_ptr_);

  transient_data.target_lane_length =
    lanelet::geometry::length2d(lanelet::LaneletSequence(common_data_ptr_->lanes_ptr->target));

  transient_data.current_lanes_ego_arc =
    autoware::experimental::lanelet2_utils::get_arc_coordinates(
      common_data_ptr_->lanes_ptr->current, common_data_ptr_->get_ego_pose());

  transient_data.target_lanes_ego_arc = autoware::experimental::lanelet2_utils::get_arc_coordinates(
    common_data_ptr_->lanes_ptr->target, common_data_ptr_->get_ego_pose());

  transient_data.is_ego_near_current_terminal_start =
    transient_data.dist_to_terminal_start < transient_data.max_prepare_length;

  transient_data.current_footprint = utils::lane_change::get_ego_footprint(
    common_data_ptr_->get_ego_pose(), common_data_ptr_->bpp_param_ptr->vehicle_info);

  transient_data.ego_to_terminal_end_proximity =
    utils::lane_change::calc_polygon_dist_range_from_terminal_end(
      common_data_ptr_->current_lanes_path, transient_data.current_footprint);

  const auto & ego_lane = common_data_ptr_->lanes_ptr->ego_lane;
  const auto & route_handler_ptr = common_data_ptr_->route_handler_ptr;
  transient_data.in_intersection = utils::lane_change::is_within_intersection(
    route_handler_ptr, ego_lane, transient_data.current_footprint);
  transient_data.in_turn_direction_lane =
    utils::lane_change::is_within_turn_direction_lanes(ego_lane, transient_data.current_footprint);

  transient_data.interval_dist_no_lane_change_lines =
    utils::lane_change::get_interval_dist_no_lane_change_lines(
      common_data_ptr_->no_lane_change_lines, common_data_ptr_->current_lanes_path,
      common_data_ptr_->get_ego_pose());

  update_dist_from_intersection();

  updateStopTime();
  transient_data.is_ego_stuck = is_ego_stuck();

  RCLCPP_DEBUG(
    logger_, "lane_changing_length - min: %.4f, max: %.4f", transient_data.lane_changing_length.min,
    transient_data.lane_changing_length.max);
  RCLCPP_DEBUG(
    logger_, "current_dist_buffer - min: %.4f, max: %.4f", transient_data.current_dist_buffer.min,
    transient_data.current_dist_buffer.max);
  RCLCPP_DEBUG(
    logger_, "next_dist_buffer - min: %.4f, max: %.4f", transient_data.next_dist_buffer.min,
    transient_data.next_dist_buffer.max);
  RCLCPP_DEBUG(logger_, "dist_to_terminal_start: %.4f", transient_data.dist_to_terminal_start);
  RCLCPP_DEBUG(logger_, "dist_to_terminal_end: %.4f", transient_data.dist_to_terminal_end);
  RCLCPP_DEBUG(logger_, "max_prepare_length: %.4f", transient_data.max_prepare_length);
  RCLCPP_DEBUG(
    logger_, "is_ego_near_current_terminal_start: %s",
    (transient_data.is_ego_near_current_terminal_start ? "true" : "false"));
}

