bool NormalLaneChange::get_path_using_frenet(
  const std::vector<LaneChangePhaseMetrics> & prepare_metrics,
  const lane_change::TargetObjects & target_objects,
  const std::vector<std::vector<int64_t>> & sorted_lane_ids,
  LaneChangePaths & candidate_paths) const
{
  stop_watch_.tic(__func__);
  constexpr auto found_safe_path = true;
  const auto frenet_candidates = utils::lane_change::generate_frenet_candidates(
    common_data_ptr_, prev_module_output_.path, prepare_metrics);
  RCLCPP_DEBUG(
    logger_, "Generated %lu candidate paths in %2.2f[us]", frenet_candidates.size(),
    stop_watch_.toc(__func__));

  candidate_paths.reserve(frenet_candidates.size());
  lane_change_debug_.frenet_states.clear();
  lane_change_debug_.frenet_states.reserve(frenet_candidates.size());
  for (const auto & frenet_candidate : frenet_candidates) {
    if (stop_watch_.toc(__func__) >= lane_change_parameters_->time_limit) {
      break;
    }

    lane_change_debug_.frenet_states.emplace_back(
      frenet_candidate.prepare_metric, frenet_candidate.lane_changing.sampling_parameter,
      frenet_candidate.lc_average_curvature, frenet_candidate.max_lane_changing_length);

    std::optional<LaneChangePath> candidate_path_opt;
    try {
      candidate_path_opt =
        utils::lane_change::get_candidate_path(frenet_candidate, common_data_ptr_, sorted_lane_ids);
    } catch (const std::exception & e) {
      RCLCPP_DEBUG(logger_, "%s", e.what());
    }

    if (!candidate_path_opt) {
      continue;
    }

    try {
      if (check_candidate_path_safety(*candidate_path_opt, target_objects)) {
        RCLCPP_DEBUG(
          logger_, "Found safe path after %lu candidate(s). Total time: %2.2f[us]",
          frenet_candidates.size(), stop_watch_.toc(__func__));
        utils::lane_change::append_target_ref_to_candidate(
          *candidate_path_opt, common_data_ptr_->lc_param_ptr->frenet.th_curvature_smoothing);
        candidate_paths.push_back(*candidate_path_opt);
        return found_safe_path;
      }
    } catch (const std::exception & e) {
      RCLCPP_DEBUG(logger_, "%s", e.what());
    }

    // appending all paths affect performance
    if (candidate_paths.empty()) {
      candidate_paths.push_back(*candidate_path_opt);
    }
  }

  RCLCPP_DEBUG(
    logger_, "No safe path after %lu candidate(s). Total time: %2.2f[us]", frenet_candidates.size(),
    stop_watch_.toc(__func__));
  return !found_safe_path;
}

std::vector<lane_change::TrajectoryGroup> generate_frenet_candidates(
  const CommonDataPtr & common_data_ptr, const PathWithLaneId & prev_module_path,
  const std::vector<LaneChangePhaseMetrics> & prep_metrics)
{
  std::vector<lane_change::TrajectoryGroup> trajectory_groups;
  autoware_utils::StopWatch<std::chrono::microseconds> sw;

  const auto & transient_data = common_data_ptr->transient_data;
  const auto & current_lanes = common_data_ptr->lanes_ptr->current;
  const auto & target_lanes = common_data_ptr->lanes_ptr->target;
  const auto direction = common_data_ptr->direction;
  const auto current_lane_boundary = get_linestring_bound(current_lanes, direction);

  for (const auto & metric : prep_metrics) {
    PathWithLaneId prepare_segment;
    try {
      if (!utils::lane_change::get_prepare_segment(
            common_data_ptr, prev_module_path, metric.length, prepare_segment)) {
        RCLCPP_DEBUG(get_logger(), "Reject: failed to get valid prepare segment!");
        continue;
      }
    } catch (const std::exception & e) {
      RCLCPP_WARN(get_logger(), "%s", e.what());
      break;
    }
    const auto lc_start_pose = prepare_segment.points.back().point.pose;

    const auto dist_to_end_from_lc_start =
      calculation::calc_dist_from_pose_to_terminal_end(
        common_data_ptr, target_lanes, lc_start_pose) -
      common_data_ptr->lc_param_ptr->lane_change_finish_judge_buffer;
    const auto max_lc_len = transient_data.lane_changing_length.max;
    const auto max_lane_changing_length = std::min(dist_to_end_from_lc_start, max_lc_len);

    constexpr auto resample_interval = 0.5;
    const auto target_lane_reference_path = get_reference_path_from_target_lane(
      common_data_ptr, lc_start_pose, max_lane_changing_length, resample_interval);
    if (target_lane_reference_path.points.empty()) {
      continue;
    }

    std::vector<double> target_ref_path_sums{0.0};
    target_ref_path_sums.reserve(target_lane_reference_path.points.size() - 1);
    double ref_s = 0.0;
    for (auto it = target_lane_reference_path.points.begin();
         std::next(it) != target_lane_reference_path.points.end(); ++it) {
      ref_s += autoware_utils::calc_distance2d(*it, *std::next(it));
      target_ref_path_sums.push_back(ref_s);
    }

    const auto reference_spline = init_reference_spline(target_lane_reference_path.points);

    const auto initial_state = init_frenet_state(
      reference_spline.frenet({lc_start_pose.position.x, lc_start_pose.position.y}), metric);

    RCLCPP_DEBUG(
      get_logger(), "Initial state [s=%2.2f, d=%2.2f, s'=%2.2f, d'=%2.2f, s''=%2.2f, d''=%2.2f]",
      initial_state.position.s, initial_state.position.d, initial_state.longitudinal_velocity,
      initial_state.lateral_velocity, initial_state.longitudinal_acceleration,
      initial_state.lateral_acceleration);

    const auto sampling_parameters_opt =
      init_sampling_parameters(common_data_ptr, metric, initial_state, reference_spline);

    if (!sampling_parameters_opt) {
      continue;
    }

    auto frenet_trajectories = frenet_planner::generateTrajectories(
      reference_spline, initial_state, *sampling_parameters_opt);

    trajectory_groups.reserve(trajectory_groups.size() + frenet_trajectories.size());
    for (const auto & traj : frenet_trajectories) {
      if (!trajectory_groups.empty()) {
        const auto diff = std::abs(
          traj.frenet_points.back().s -
          trajectory_groups.back().lane_changing.frenet_points.back().s);
        if (diff < common_data_ptr->lc_param_ptr->trajectory.th_lane_changing_length_diff) {
          continue;
        }
      }

      const auto out_of_bound =
        check_out_of_bound_paths(common_data_ptr, traj.poses, current_lane_boundary, direction);

      if (out_of_bound) {
        continue;
      }

      const auto lane_changing_average_curvature = calc_average_curvature(traj.curvatures);
      trajectory_groups.emplace_back(
        prepare_segment, target_lane_reference_path, target_ref_path_sums, metric, traj,
        initial_state, lane_changing_average_curvature, max_lane_changing_length);
    }
  }

  const auto limit_vel = [&](TrajectoryGroup & group) {
    const auto max_vel = calc_limit(common_data_ptr, group.lane_changing.poses.back());
    for (auto & vel : group.lane_changing.longitudinal_velocities) {
      vel = std::clamp(vel, 0.0, max_vel);
    }
  };

  ranges::for_each(trajectory_groups, limit_vel);

  ranges::sort(trajectory_groups, [&](const auto & p1, const auto & p2) {
    return p1.lc_average_curvature < p2.lc_average_curvature;
  });

  if (trajectory_groups.size() > 1) {
    auto subrange = ranges::subrange(trajectory_groups.begin() + 1, trajectory_groups.end());

    auto remove_start = ranges::remove_if(subrange, [&](const auto & traj) {
      return traj.lc_average_curvature > common_data_ptr->lc_param_ptr->frenet.th_average_curvature;
    });

    trajectory_groups.erase(remove_start, trajectory_groups.end());
  }

  return trajectory_groups;
}

LineString2d get_linestring_bound(const lanelet::ConstLanelets & lanes, const Direction direction)
{
  LineString2d line_string;
  const auto & get_bound = [&](const lanelet::ConstLanelet & lane) {
    return (direction == Direction::LEFT) ? lane.leftBound2d() : lane.rightBound2d();
  };

  const auto reserve_size = ranges::accumulate(
    lanes, 0UL,
    [&](auto sum, const lanelet::ConstLanelet & lane) { return sum + get_bound(lane).size(); });
  line_string.reserve(reserve_size);
  for (const auto & lane : lanes) {
    ranges::for_each(get_bound(lane), [&line_string](const auto & point) {
      boost::geometry::append(line_string, Point2d(point.x(), point.y()));
    });
  }
  return line_string;
}

bool get_prepare_segment(
  const CommonDataPtr & common_data_ptr, const PathWithLaneId & prev_module_path,
  const double prep_length, PathWithLaneId & prepare_segment)
{
  const auto & current_lanes = common_data_ptr->lanes_ptr->current;
  const auto & target_lanes = common_data_ptr->lanes_ptr->target;
  const auto backward_path_length = common_data_ptr->bpp_param_ptr->backward_path_length;

  if (current_lanes.empty() || target_lanes.empty()) {
    throw std::logic_error("Empty lanes!");
  }

  prepare_segment = prev_module_path;
  const size_t current_seg_idx =
    autoware::motion_utils::findFirstNearestSegmentIndexWithSoftConstraints(
      prepare_segment.points, common_data_ptr->get_ego_pose(), 3.0, 1.0);
  utils::clipPathLength(prepare_segment, current_seg_idx, prep_length, backward_path_length);

  if (prepare_segment.points.empty()) return false;

  const auto & lc_start_pose = prepare_segment.points.back().point.pose;

  // TODO(Quda, Azu): Is it possible to remove these checks if we ensure prepare segment length is
  // larger than distance to target lane start
  if (!is_valid_start_point(common_data_ptr, lc_start_pose)) return false;

  // lane changing start is at the end of prepare segment
  const auto target_length_from_lane_change_start_pose =
    utils::getArcLengthToTargetLanelet(current_lanes, target_lanes.front(), lc_start_pose);

  // Check if the lane changing start point is not on the lanes next to target lanes,
  if (target_length_from_lane_change_start_pose > std::numeric_limits<double>::epsilon()) {
    throw std::logic_error("lane change start is behind target lanelet!");
  }

  const auto curvatures = calc_curvatures(prepare_segment.points, common_data_ptr->get_ego_pose());

  // curvatures may be empty if ego is near the terminal start of the path.
  if (curvatures.empty()) {
    return true;
  }

  const auto average_curvature = calc_average_curvature(curvatures);

  RCLCPP_DEBUG(get_logger(), "average curvature: %.3f", average_curvature);
  return average_curvature <= common_data_ptr->lc_param_ptr->trajectory.th_prepare_curvature;
}

size_t findFirstNearestSegmentIndexWithSoftConstraints(
  const T & points, const geometry_msgs::msg::Pose & pose,
  const double dist_threshold = std::numeric_limits<double>::max(),
  const double yaw_threshold = std::numeric_limits<double>::max())
{
  // find first nearest index with soft constraints (not segment index)
  const size_t nearest_idx =
    findFirstNearestIndexWithSoftConstraints(points, pose, dist_threshold, yaw_threshold);

  // calculate segment index
  if (nearest_idx == 0) {
    return 0;
  }
  if (nearest_idx == points.size() - 1) {
    return points.size() - 2;
  }

  const double signed_length = calcLongitudinalOffsetToSegment(points, nearest_idx, pose.position);

  if (signed_length <= 0) {
    return nearest_idx - 1;
  }

  return nearest_idx;
}

size_t findFirstNearestIndexWithSoftConstraints(
  const T & points, const geometry_msgs::msg::Pose & pose,
  const double dist_threshold = std::numeric_limits<double>::max(),
  const double yaw_threshold = std::numeric_limits<double>::max())
{
  validateNonEmpty(points);

  {  // with dist and yaw thresholds
    const double squared_dist_threshold = dist_threshold * dist_threshold;
    double min_squared_dist = std::numeric_limits<double>::max();
    size_t min_idx = 0;
    bool is_within_constraints = false;
    for (size_t i = 0; i < points.size(); ++i) {
      const auto squared_dist =
        autoware_utils_geometry::calc_squared_distance2d(points.at(i), pose.position);
      const auto yaw = autoware_utils_geometry::calc_yaw_deviation(
        autoware_utils_geometry::get_pose(points.at(i)), pose);

      if (squared_dist_threshold < squared_dist || yaw_threshold < std::abs(yaw)) {
        if (is_within_constraints) {
          break;
        }
        continue;
      }

      if (min_squared_dist <= squared_dist) {
        continue;
      }

      min_squared_dist = squared_dist;
      min_idx = i;
      is_within_constraints = true;
    }

    // nearest index is found
    if (is_within_constraints) {
      return min_idx;
    }
  }

  {  // with dist threshold
    const double squared_dist_threshold = dist_threshold * dist_threshold;
    double min_squared_dist = std::numeric_limits<double>::max();
    size_t min_idx = 0;
    bool is_within_constraints = false;
    for (size_t i = 0; i < points.size(); ++i) {
      const auto squared_dist =
        autoware_utils_geometry::calc_squared_distance2d(points.at(i), pose.position);

      if (squared_dist_threshold < squared_dist) {
        if (is_within_constraints) {
          break;
        }
        continue;
      }

      if (min_squared_dist <= squared_dist) {
        continue;
      }

      min_squared_dist = squared_dist;
      min_idx = i;
      is_within_constraints = true;
    }

    // nearest index is found
    if (is_within_constraints) {
      return min_idx;
    }
  }

  {  // with yaw threshold
    double min_squared_dist = std::numeric_limits<double>::max();
    size_t min_idx = 0;
    bool is_within_constraints = false;
    for (size_t i = 0; i < points.size(); ++i) {
      const auto yaw = autoware_utils_geometry::calc_yaw_deviation(
        autoware_utils_geometry::get_pose(points.at(i)), pose);

      if (yaw_threshold < std::abs(yaw)) {
        if (is_within_constraints) {
          break;
        }
        continue;
      }

      const auto squared_dist =
        autoware_utils_geometry::calc_squared_distance2d(points.at(i), pose.position);
      if (min_squared_dist <= squared_dist) {
        continue;
      }

      min_squared_dist = squared_dist;
      min_idx = i;
      is_within_constraints = true;
    }

    // nearest index is found
    if (is_within_constraints) {
      return min_idx;
    }
  }

  // without any threshold
  return findNearestIndex(points, pose.position);
}

double calc_squared_distance2d(const Point1 & point1, const Point2 & point2)
{
  const auto p1 = get_point(point1);
  const auto p2 = get_point(point2);
  const auto dx = p1.x - p2.x;
  const auto dy = p1.y - p2.y;
  return dx * dx + dy * dy;
}

geometry_msgs::msg::Point get_point(const T & p)
{
  return geometry_msgs::build<geometry_msgs::msg::Point>().x(p.x).y(p.y).z(p.z);
}

double calc_yaw_deviation(
  const geometry_msgs::msg::Pose & base_pose, const geometry_msgs::msg::Pose & target_pose)
{
  const auto base_yaw = tf2::getYaw(base_pose.orientation);
  const auto target_yaw = tf2::getYaw(target_pose.orientation);
  return autoware_utils_math::normalize_radian(target_yaw - base_yaw);
}

inline double normalize_radian(const double rad, const double min_rad = -pi)
{
  const auto max_rad = min_rad + 2 * pi;

  const auto value = std::fmod(rad, 2 * pi);
  if (min_rad <= value && value < max_rad) {
    return value;
  }

  return value - std::copysign(2 * pi, value);
}

[[nodiscard]] size_t findNearestIndex(const T & points, const geometry_msgs::msg::Point & point)
{
  validateNonEmpty(points);

  double min_dist = std::numeric_limits<double>::max();
  size_t min_idx = 0;

  for (size_t i = 0; i < points.size(); ++i) {
    const auto dist = autoware_utils_geometry::calc_squared_distance2d(points.at(i), point);
    if (dist < min_dist) {
      min_dist = dist;
      min_idx = i;
    }
  }
  return min_idx;
}

double calc_squared_distance2d(const Point1 & point1, const Point2 & point2)
{
  const auto p1 = get_point(point1);
  const auto p2 = get_point(point2);
  const auto dx = p1.x - p2.x;
  const auto dy = p1.y - p2.y;
  return dx * dx + dy * dy;
}

geometry_msgs::msg::Point get_point(const T & p)
{
  return geometry_msgs::build<geometry_msgs::msg::Point>().x(p.x).y(p.y).z(p.z);
}

double calcLongitudinalOffsetToSegment(
  const T & points, const size_t seg_idx, const geometry_msgs::msg::Point & p_target,
  const bool throw_exception = false)
{
  if (seg_idx >= points.size() - 1) {
    const std::string error_message(
      "[autoware_motion_utils] " + std::string(__func__) +
      ": Failed to calculate longitudinal offset because the given segment index is out of the "
      "points size.");
    autoware_utils_system::print_backtrace();
    if (throw_exception) {
      throw std::out_of_range(error_message);
    }
    RCLCPP_DEBUG(
      get_logger(),
      "%s Return NaN since no_throw option is enabled. The maintainer must check the code.",
      error_message.c_str());
    return std::nan("");
  }

  const auto overlap_removed_points = removeOverlapPoints(points, seg_idx);

  if (throw_exception) {
    validateNonEmpty(overlap_removed_points);
  } else {
    try {
      validateNonEmpty(overlap_removed_points);
    } catch (const std::exception & e) {
      RCLCPP_DEBUG(get_logger(), "%s", e.what());
      return std::nan("");
    }
  }

  if (seg_idx >= overlap_removed_points.size() - 1) {
    const std::string error_message(
      "[autoware_motion_utils] " + std::string(__func__) +
      ": Longitudinal offset calculation is not supported for the same points.");
    autoware_utils_system::print_backtrace();
    if (throw_exception) {
      throw std::runtime_error(error_message);
    }
    RCLCPP_DEBUG(
      get_logger(),
      "%s Return NaN since no_throw option is enabled. The maintainer must check the code.",
      error_message.c_str());
    return std::nan("");
  }

  const auto p_front = autoware_utils_geometry::get_point(overlap_removed_points.at(seg_idx));
  const auto p_back = autoware_utils_geometry::get_point(overlap_removed_points.at(seg_idx + 1));

  const Eigen::Vector3d segment_vec{p_back.x - p_front.x, p_back.y - p_front.y, 0};
  const Eigen::Vector3d target_vec{p_target.x - p_front.x, p_target.y - p_front.y, 0};

  return segment_vec.dot(target_vec) / segment_vec.norm();
}

[[nodiscard]] T removeOverlapPoints(const T & points, const size_t start_idx = 0)
{
  if (points.size() < start_idx + 1) {
    return points;
  }

  T dst;
  dst.reserve(points.size());

  for (size_t i = 0; i <= start_idx; ++i) {
    dst.push_back(points.at(i));
  }

  constexpr double eps = 1.0E-08;
  for (size_t i = start_idx + 1; i < points.size(); ++i) {
    const auto prev_p = autoware_utils_geometry::get_point(dst.back());
    const auto curr_p = autoware_utils_geometry::get_point(points.at(i));
    if (std::abs(prev_p.x - curr_p.x) < eps && std::abs(prev_p.y - curr_p.y) < eps) {
      continue;
    }
    dst.push_back(points.at(i));
  }

  return dst;
}

geometry_msgs::msg::Point get_point(const T & p)
{
  return geometry_msgs::build<geometry_msgs::msg::Point>().x(p.x).y(p.y).z(p.z);
}

geometry_msgs::msg::Point get_point(const T & p)
