double get_distance_to_next_regulatory_element(
  const CommonDataPtr & common_data_ptr, const bool ignore_crosswalk,
  const bool ignore_intersection)
{
  double distance = std::numeric_limits<double>::max();

  const auto current_pose = common_data_ptr->get_ego_pose();
  const auto & current_lanes = common_data_ptr->lanes_ptr->current;
  const auto & route_handler = *common_data_ptr->route_handler_ptr;
  const auto overall_graphs_ptr = route_handler.getOverallGraphPtr();

  if (!ignore_intersection && common_data_ptr->lc_param_ptr->regulate_on_intersection) {
    distance =
      std::min(distance, utils::getDistanceToNextIntersection(current_pose, current_lanes));
  }
  if (!ignore_crosswalk && common_data_ptr->lc_param_ptr->regulate_on_crosswalk) {
    distance = std::min(
      distance, utils::getDistanceToCrosswalk(current_pose, current_lanes, *overall_graphs_ptr));
  }
  if (common_data_ptr->lc_param_ptr->regulate_on_traffic_light) {
    distance = std::min(
      distance, utils::traffic_light::getDistanceToNextTrafficLight(current_pose, current_lanes));
  }

  return distance;
}

double getDistanceToNextIntersection(
  const Pose & current_pose, const lanelet::ConstLanelets & lanelets)
{
  const auto & arc_coordinates =
    autoware::experimental::lanelet2_utils::get_arc_coordinates(lanelets, current_pose);

  const auto current_lanelet_opt =
    experimental::lanelet2_utils::get_closest_lanelet(lanelets, current_pose);
  if (!current_lanelet_opt) {
    return std::numeric_limits<double>::max();
  }
  const auto & current_lanelet = current_lanelet_opt.value();

  double distance = 0;
  bool is_after_current_lanelet = false;
  for (const auto & llt : lanelets) {
    if (llt == current_lanelet) {
      is_after_current_lanelet = true;
    }
    if (is_after_current_lanelet && llt.hasAttribute("turn_direction")) {
      bool is_lane_change_yes = false;
      const auto right_line = llt.rightBound();
      if (right_line.hasAttribute(lanelet::AttributeNamesString::LaneChange)) {
        const auto attr = right_line.attribute(lanelet::AttributeNamesString::LaneChange);
        if (attr.value() == std::string("yes")) {
          is_lane_change_yes = true;
        }
      }
      const auto left_line = llt.leftBound();
      if (left_line.hasAttribute(lanelet::AttributeNamesString::LaneChange)) {
        const auto attr = left_line.attribute(lanelet::AttributeNamesString::LaneChange);
        if (attr.value() == std::string("yes")) {
          is_lane_change_yes = true;
        }
      }
      if (!is_lane_change_yes) {
        return distance - arc_coordinates.length;
      }
    }
    distance += lanelet::geometry::length3d(llt);
  }

  return std::numeric_limits<double>::max();
}

lanelet::ArcCoordinates get_arc_coordinates(
  const lanelet::ConstLanelets & lanelets, const geometry_msgs::msg::Pose & pose)
{
  // Handle empty Input (Return default ArcCoordinates)
  if (lanelets.empty()) {
    RCLCPP_WARN(
      rclcpp::get_logger("autoware_lanelet2_utility"),
      "Input lanelets is empty. Returning default ArcCoordinates (length=0, distance=0).");
    return lanelet::ArcCoordinates();
