std::vector<PhaseMetrics> calc_shift_phase_metrics(
  const CommonDataPtr & common_data_ptr, const double shift_length, const double initial_velocity,
  const double max_path_velocity, const double lon_accel, const double max_length_threshold)
{
  const auto & min_lc_vel = common_data_ptr->lc_param_ptr->trajectory.min_lane_changing_velocity;
  const auto & max_vel = common_data_ptr->bpp_param_ptr->max_vel;

  // get lateral acceleration range
  const auto [min_lateral_acc, max_lateral_acc] =
    common_data_ptr->lc_param_ptr->trajectory.lat_acc_map.find(initial_velocity);
  const auto lateral_acc_resolution =
    std::abs(max_lateral_acc - min_lateral_acc) /
    common_data_ptr->lc_param_ptr->trajectory.lat_acc_sampling_num;

  std::vector<PhaseMetrics> metrics;

  auto is_skip = [&](const double lane_changing_length) {
    if (lane_changing_length > max_length_threshold) {
      RCLCPP_DEBUG(
        get_logger(),
        "Skip: lane changing length exceeds maximum threshold. length: %.5f, threshold: %.5f",
        lane_changing_length, max_length_threshold);
      return true;
    }
    return false;
  };

  for (double lat_acc = min_lateral_acc; lat_acc < max_lateral_acc + eps;
       lat_acc += lateral_acc_resolution) {
    const auto lane_changing_duration = autoware::motion_utils::calc_shift_time_from_jerk(
      shift_length, common_data_ptr->lc_param_ptr->trajectory.lateral_jerk, lat_acc);

    const double lane_changing_accel = calc_lane_changing_acceleration(
      common_data_ptr, initial_velocity, max_path_velocity, lane_changing_duration, lon_accel);

    const auto lane_changing_length = calculation::calc_phase_length(
      initial_velocity, max_vel, lane_changing_accel, lane_changing_duration);

    if (is_skip(lane_changing_length)) continue;

    const auto lane_changing_velocity = std::clamp(
      initial_velocity + lane_changing_accel * lane_changing_duration, min_lc_vel, max_vel);

    metrics.emplace_back(
      lane_changing_duration, lane_changing_length, lane_changing_velocity, lon_accel,
      lane_changing_accel, lat_acc);
  }

  return metrics;
}

double calc_shift_time_from_jerk(const double lateral, const double jerk, const double acc)
{
  const double j = std::abs(jerk);
  const double a = std::abs(acc);
  const double l = std::abs(lateral);
  if (j < 1.0e-8 || a < 1.0e-8) {
    const std::string error_message(
      std::string(__func__) + ": Failed to calculate shift time due to invalid arg");
    RCLCPP_WARN(get_logger(), "%s", error_message.c_str());
    return 1.0e10;  // TODO(Horibe) maybe invalid arg?
  }

  // time with constant jerk
  double tj = a / j;

  // time with constant acceleration (zero jerk)
  double ta = (std::sqrt(a * a + 4.0 * j * j * l / a) - 3.0 * a) / (2.0 * j);

  if (ta < 0.0) {
    // it will not hit the acceleration limit this time
    tj = std::pow(l / (2.0 * j), 1.0 / 3.0);
    ta = 0.0;
  }

  const double t_total = 4.0 * tj + 2.0 * ta;
  return t_total;
}

double calc_lane_changing_acceleration(
  const CommonDataPtr & common_data_ptr, const double initial_lane_changing_velocity,
  const double max_path_velocity, const double lane_changing_time,
  const double prepare_longitudinal_acc)
{
  if (prepare_longitudinal_acc <= 0.0) {
    const auto & params = common_data_ptr->lc_param_ptr->trajectory;
    const auto lane_changing_acc =
      common_data_ptr->transient_data.is_ego_near_current_terminal_start
        ? prepare_longitudinal_acc * params.lane_changing_decel_factor
        : 0.0;
    return lane_changing_acc;
  }

  return std::clamp(
    (max_path_velocity - initial_lane_changing_velocity) / lane_changing_time, 0.0,
    prepare_longitudinal_acc);
}

double calc_phase_length(
  const double velocity, const double maximum_velocity, const double acceleration,
  const double duration)
{
  const auto length_with_acceleration =
    velocity * duration + 0.5 * acceleration * std::pow(duration, 2);
  const auto length_with_max_velocity = maximum_velocity * duration;
  return std::min(length_with_acceleration, length_with_max_velocity);
}

void set_prepare_velocity(
  PathWithLaneId & prepare_segment, const double current_velocity, const double prepare_velocity)
{
  if (current_velocity >= prepare_velocity) {
    // deceleration
    prepare_segment.points.back().point.longitudinal_velocity_mps = std::min(
      prepare_segment.points.back().point.longitudinal_velocity_mps,
      static_cast<float>(prepare_velocity));
    return;
  }
  // acceleration
  for (auto & point : prepare_segment.points) {
    point.point.longitudinal_velocity_mps =
      std::min(point.point.longitudinal_velocity_mps, static_cast<float>(prepare_velocity));
  }
}

std::optional<LaneChangePath> get_candidate_path(
  const TrajectoryGroup & trajectory_group, const CommonDataPtr & common_data_ptr,
  const std::vector<std::vector<int64_t>> & sorted_lane_ids)
{
  if (trajectory_group.lane_changing.frenet_points.empty()) {
    return std::nullopt;
  }

  ShiftedPath shifted_path;
  std::vector<int64_t> prev_ids;
  std::vector<int64_t> prev_sorted_ids;
  const auto & lane_changing_candidate = trajectory_group.lane_changing;
  const auto & target_lane_ref_path = trajectory_group.target_lane_ref_path;
  const auto & prepare_segment = trajectory_group.prepare;
  const auto & prepare_metric = trajectory_group.prepare_metric;
  const auto & initial_state = trajectory_group.initial_state;
  const auto & target_ref_sums = trajectory_group.target_lane_ref_path_dist;
  auto zipped_candidates = ranges::views::zip(
    lane_changing_candidate.poses, lane_changing_candidate.frenet_points,
    lane_changing_candidate.longitudinal_velocities, lane_changing_candidate.lateral_velocities,
    lane_changing_candidate.curvatures);

  shifted_path.path.points.reserve(zipped_candidates.size());
  shifted_path.shift_length.reserve(zipped_candidates.size());
  for (const auto & [pose, frenet_point, longitudinal_velocity, lateral_velocity, curvature] :
       zipped_candidates) {
    // Find the reference index
    const auto & s = frenet_point.s;
    auto ref_i_itr = std::find_if(
      target_ref_sums.begin(), target_ref_sums.end(),
      [s](const double ref_s) { return ref_s > s; });
    auto ref_i = std::distance(target_ref_sums.begin(), ref_i_itr);

    PathPointWithLaneId point;
    point.point.pose = pose;
    point.point.longitudinal_velocity_mps = static_cast<float>(longitudinal_velocity);
    point.point.lateral_velocity_mps = static_cast<float>(lateral_velocity);
    point.point.heading_rate_rps = static_cast<float>(curvature);
    point.point.pose.position.z = target_lane_ref_path.points[ref_i].point.pose.position.z;
    const auto & current_ids = target_lane_ref_path.points[ref_i].lane_ids;
    point.lane_ids =
      replace_with_sorted_ids(current_ids, sorted_lane_ids, prev_ids, prev_sorted_ids);

    // Add to shifted path
    shifted_path.shift_length.push_back(frenet_point.d);
    shifted_path.path.points.push_back(point);
  }

  if (shifted_path.path.points.empty()) {
    return std::nullopt;
  }

  for (auto & point : shifted_path.path.points) {
    point.point.longitudinal_velocity_mps = std::min(
      point.point.longitudinal_velocity_mps,
      static_cast<float>(shifted_path.path.points.back().point.longitudinal_velocity_mps));
  }

  const auto th_yaw_diff_deg = common_data_ptr->lc_param_ptr->frenet.th_yaw_diff_deg;
  if (
    const auto yaw_diff_opt = exceed_yaw_threshold(
      prepare_segment, shifted_path.path, autoware_utils::deg2rad(th_yaw_diff_deg))) {
    const auto yaw_diff_deg = autoware_utils::rad2deg(yaw_diff_opt.value());
    const auto err_msg = fmt::format(
      "Excessive yaw difference {yaw_diff:2.2f}[deg]. The threshold is {th_yaw_diff:2.2f}[deg].",
      fmt::arg("yaw_diff", yaw_diff_deg), fmt::arg("th_yaw_diff", th_yaw_diff_deg));
    throw std::logic_error(err_msg);
  }

  LaneChangeInfo info;
  info.longitudinal_acceleration = {
    prepare_metric.actual_lon_accel, lane_changing_candidate.longitudinal_accelerations.front()};
  info.velocity = {prepare_metric.velocity, initial_state.longitudinal_velocity};
  info.duration = {
    prepare_metric.duration, lane_changing_candidate.sampling_parameter.target_duration};
  info.length = {prepare_metric.length, lane_changing_candidate.lengths.back()};
  info.lane_changing_start = prepare_segment.points.back().point.pose;
  info.lane_changing_end = lane_changing_candidate.poses.back();

  if (utils::lane_change::is_intersecting_no_lane_change_lines(
        common_data_ptr, info.length, shifted_path.path.points)) {
    throw std::logic_error("Intersect no lane change lines.");
  }

  ShiftLine sl;

  sl.start = lane_changing_candidate.poses.front();
  sl.end = lane_changing_candidate.poses.back();
  sl.start_shift_length = 0.0;
  sl.end_shift_length = initial_state.position.d;
  sl.start_idx = 0UL;
  sl.end_idx = shifted_path.shift_length.size() - 1;

  info.shift_line = sl;
  info.terminal_lane_changing_velocity = lane_changing_candidate.longitudinal_velocities.back();
  info.lateral_acceleration = lane_changing_candidate.lateral_accelerations.front();

  LaneChangePath candidate_path;
  candidate_path.path = utils::combinePath(prepare_segment, shifted_path.path);
  candidate_path.info = info;
  candidate_path.shifted_path = shifted_path;
  candidate_path.frenet_path = trajectory_group;
  candidate_path.type = PathType::FrenetPlanner;

  return candidate_path;
}

std::vector<int64_t> replace_with_sorted_ids(
  const std::vector<int64_t> & current_lane_ids,
  const std::vector<std::vector<int64_t>> & sorted_lane_ids, std::vector<int64_t> & prev_lane_ids,
  std::vector<int64_t> & prev_sorted_lane_ids)
{
  if (current_lane_ids == prev_lane_ids) {
    return prev_sorted_lane_ids;
  }

  for (const auto original_id : current_lane_ids) {
    for (const auto & sorted_id : sorted_lane_ids) {
      if (std::find(sorted_id.cbegin(), sorted_id.cend(), original_id) != sorted_id.cend()) {
        prev_lane_ids = current_lane_ids;
        prev_sorted_lane_ids = sorted_id;
        return prev_sorted_lane_ids;
      }
    }
  }

  return current_lane_ids;
}

std::optional<double> exceed_yaw_threshold(
  const PathWithLaneId & prepare_segment, const PathWithLaneId & lane_changing_segment,
  const double yaw_th_rad)
{
  const auto & prepare = prepare_segment.points;
  const auto & lane_changing = lane_changing_segment.points;

  if (prepare.size() <= 1 || lane_changing.size() <= 1) {
    return std::nullopt;
  }

  const auto & p1 = std::prev(prepare.end() - 1)->point.pose;
  const auto & p2 = std::next(lane_changing.begin())->point.pose;
  const auto yaw_diff_rad = std::abs(
    autoware_utils::normalize_radian(tf2::getYaw(p1.orientation) - tf2::getYaw(p2.orientation)));
  if (yaw_diff_rad > yaw_th_rad) {
    return yaw_diff_rad;
  }
  return std::nullopt;
}

inline double normalize_radian(const double rad, const double min_rad = -pi)
{
  const auto max_rad = min_rad + 2 * pi;

  const auto value = std::fmod(rad, 2 * pi);
  if (min_rad <= value && value < max_rad) {
    return value;
  }

  return value - std::copysign(2 * pi, value);
}

PathWithLaneId combinePath(const PathWithLaneId & path1, const PathWithLaneId & path2)
{
  if (path1.points.empty()) {
    return path2;
  }
  if (path2.points.empty()) {
    return path1;
  }

  PathWithLaneId path{};
  path.points.insert(path.points.end(), path1.points.begin(), path1.points.end());

  // skip overlapping point
  path.points.insert(path.points.end(), next(path2.points.begin()), path2.points.end());

  PathWithLaneId filtered_path = path;
  filtered_path.points = autoware::motion_utils::removeOverlapPoints(filtered_path.points);
  return filtered_path;
}

[[nodiscard]] T removeOverlapPoints(const T & points, const size_t start_idx = 0)
{
  if (points.size() < start_idx + 1) {
    return points;
  }

  T dst;
  dst.reserve(points.size());

  for (size_t i = 0; i <= start_idx; ++i) {
    dst.push_back(points.at(i));
  }

  constexpr double eps = 1.0E-08;
  for (size_t i = start_idx + 1; i < points.size(); ++i) {
    const auto prev_p = autoware_utils_geometry::get_point(dst.back());
    const auto curr_p = autoware_utils_geometry::get_point(points.at(i));
    if (std::abs(prev_p.x - curr_p.x) < eps && std::abs(prev_p.y - curr_p.y) < eps) {
      continue;
    }
    dst.push_back(points.at(i));
  }

  return dst;
}

geometry_msgs::msg::Point get_point(const T & p)
{
  return geometry_msgs::build<geometry_msgs::msg::Point>().x(p.x).y(p.y).z(p.z);
}

bool NormalLaneChange::check_candidate_path_safety(
  const LaneChangePath & candidate_path, const lane_change::TargetObjects & target_objects) const
{
  const auto is_stuck = common_data_ptr_->transient_data.is_ego_stuck;
  if (utils::lane_change::has_overtaking_turn_lane_object(
        common_data_ptr_, filtered_objects_.target_lane_trailing)) {
    throw std::logic_error("Ego is nearby intersection, and there might be overtaking vehicle.");
  }

  if (
    !is_stuck && utils::lane_change::is_delay_lane_change(
                   common_data_ptr_, candidate_path, filtered_objects_.target_lane_leading.stopped,
                   lane_change_debug_.collision_check_objects)) {
    throw std::logic_error(
      "Ego is not stuck and parked vehicle exists in the target lane. Skip lane change.");
  }

  const auto lc_start_velocity = candidate_path.info.velocity.prepare;
  const auto min_lc_velocity = lane_change_parameters_->trajectory.min_lane_changing_velocity;
  constexpr double margin = 0.1;
  // path is unsafe if it exceeds target lane boundary with a high velocity
  if (
    lane_change_parameters_->safety.enable_target_lane_bound_check &&
    lc_start_velocity > min_lc_velocity + margin &&
    utils::lane_change::path_footprint_exceeds_target_lane_bound(
      common_data_ptr_, candidate_path.shifted_path.path, planner_data_->parameters.vehicle_info)) {
    throw std::logic_error("Path footprint exceeds target lane boundary. Skip lane change.");
  }

  if ((target_objects.empty()) || candidate_path.path.points.empty()) {
    RCLCPP_DEBUG(logger_, "There is nothing to check.");
    return true;
  }

  constexpr size_t decel_sampling_num = 1;
  const auto ego_predicted_paths = utils::lane_change::convert_to_predicted_paths(
    common_data_ptr_, candidate_path, decel_sampling_num);

  const auto safety_check_with_normal_rss = isLaneChangePathSafe(
    candidate_path, ego_predicted_paths, target_objects,
    common_data_ptr_->lc_param_ptr->safety.rss_params, lane_change_debug_.collision_check_objects);

  if (!safety_check_with_normal_rss.is_safe && is_stuck) {
    const auto safety_check_with_stuck_rss = isLaneChangePathSafe(
      candidate_path, ego_predicted_paths, target_objects,
      common_data_ptr_->lc_param_ptr->safety.rss_params_for_stuck,
      lane_change_debug_.collision_check_objects);
    return safety_check_with_stuck_rss.is_safe;
  }

  return safety_check_with_normal_rss.is_safe;
}

bool has_overtaking_turn_lane_object(
  const CommonDataPtr & common_data_ptr, const ExtendedPredictedObjects & trailing_objects)
{
  // Note: This situation is only applicable if the ego is in a turn lane.
  if (has_passed_intersection_turn_direction(common_data_ptr)) {
    return false;
  }

  const auto is_object_overlap_with_target = [&](const auto & object) {
    // to compensate for perception issue, or if object is from behind ego, and tries to overtake,
    // but stop all of sudden
    if (!boost::geometry::disjoint(
          object.initial_polygon, common_data_ptr->lanes_polygon_ptr->current)) {
      return true;
    }

    return object_path_overlaps_lanes(object, common_data_ptr->lanes_polygon_ptr->target);
  };

  return std::any_of(
    trailing_objects.begin(), trailing_objects.end(), is_object_overlap_with_target);
}

bool has_passed_intersection_turn_direction(const CommonDataPtr & common_data_ptr)
{
  const auto & transient_data = common_data_ptr->transient_data;
  if (transient_data.in_intersection && transient_data.in_turn_direction_lane) {
    return false;
  }

  return transient_data.dist_from_prev_intersection >
         common_data_ptr->lc_param_ptr->backward_length_from_intersection;
}

bool object_path_overlaps_lanes(
  const ExtendedPredictedObject & object, const lanelet::BasicPolygon2d & lanes_polygon)
{
  return ranges::any_of(get_line_string_paths(object), [&](const auto & path) {
    return !boost::geometry::disjoint(path, lanes_polygon);
  });
}

std::vector<LineString2d> get_line_string_paths(const ExtendedPredictedObject & object)
{
  const auto to_linestring_2d = [](const auto & predicted_path) -> LineString2d {
    LineString2d line_string;
    const auto & path = predicted_path.path;
    line_string.reserve(path.size());
    for (const auto & path_point : path) {
      const auto point = autoware_utils::from_msg(path_point.pose.position).to_2d();
      line_string.push_back(point);
    }

    return line_string;
  };

  return object.predicted_paths | ranges::views::transform(to_linestring_2d) |
         ranges::to<std::vector>();
}

bool is_delay_lane_change(
  const CommonDataPtr & common_data_ptr, const LaneChangePath & lane_change_path,
  const ExtendedPredictedObjects & target_objects, CollisionCheckDebugMap & object_debug)
{
  const auto & current_lane_path = common_data_ptr->current_lanes_path;
  const auto & delay_lc_param = common_data_ptr->lc_param_ptr->delay;

  if (
    !delay_lc_param.enable || target_objects.empty() || lane_change_path.path.points.empty() ||
    current_lane_path.points.empty()) {
    return false;
  }

  const auto dist_to_end = common_data_ptr->transient_data.dist_to_terminal_end;
  const auto dist_buffer = common_data_ptr->transient_data.current_dist_buffer.min;
  auto is_near_end = [&dist_to_end, &dist_buffer](const ExtendedPredictedObject & obj) {
    const auto dist_obj_to_end = dist_to_end - obj.dist_from_ego;
    return dist_obj_to_end <= dist_buffer;
  };

  const auto ego_vel = common_data_ptr->get_ego_speed();
  const auto min_lon_acc = common_data_ptr->lc_param_ptr->trajectory.min_longitudinal_acc;
  const auto gap_threshold = std::abs((ego_vel * ego_vel) / (2 * min_lon_acc));
  auto is_sufficient_gap = [&gap_threshold](const auto & current_obj, const auto & next_obj) {
    const auto curr_obj_half_length = current_obj.shape.dimensions.x;
    const auto next_obj_half_length = next_obj.shape.dimensions.x;
    const auto dist_current_to_next = next_obj.dist_from_ego - current_obj.dist_from_ego;
    const auto gap_length = dist_current_to_next - curr_obj_half_length - next_obj_half_length;
    return gap_length > gap_threshold;
  };

  for (auto it = target_objects.begin(); it < target_objects.end(); ++it) {
    if (is_near_end(*it)) break;

    if (it->dist_from_ego < lane_change_path.info.length.lane_changing) continue;

    if (
      delay_lc_param.check_only_parked_vehicle &&
      !isParkedObject(
        lane_change_path.path, *common_data_ptr->route_handler_ptr, *it,
        delay_lc_param.min_road_shoulder_width, delay_lc_param.th_parked_vehicle_shift_ratio)) {
      continue;
    }

    auto next_it = std::next(it);
    if (next_it == target_objects.end() || is_sufficient_gap(*it, *next_it)) {
      auto debug = utils::path_safety_checker::createObjectDebug(*it);
      debug.second.unsafe_reason = "delay lane change";
      utils::path_safety_checker::updateCollisionCheckDebugMap(object_debug, debug, false);
      return true;
    }
  }

  return false;
}

[[nodiscard]] double get_ego_speed(bool use_norm = false) const
{
  if (!use_norm) {
    return get_ego_twist().linear.x;
  }

  const auto x = get_ego_twist().linear.x;
  const auto y = get_ego_twist().linear.y;
  return std::hypot(x, y);
}

bool isParkedObject(
  const PathWithLaneId & path, const RouteHandler & route_handler,
  const ExtendedPredictedObject & object, const double object_check_min_road_shoulder_width,
  const double object_shiftable_ratio_threshold, const double static_object_velocity_threshold)
{
  // ============================================ <- most_left_lanelet.leftBound()
  // y              road shoulder
  // ^ ------------------------------------------
  // |   x                                +
  // +---> --- object closest lanelet --- o ----- <- object_closest_lanelet.centerline()
  //
  // --------------------------------------------
  // +: object position
  // o: nearest point on centerline

  const double object_vel_norm =
    std::hypot(object.initial_twist.linear.x, object.initial_twist.linear.y);
  if (object_vel_norm > static_object_velocity_threshold) {
    return false;
  }

  const auto & object_pose = object.initial_pose;
  const auto object_closest_index =
    autoware::motion_utils::findNearestIndex(path.points, object_pose.position);
  const auto object_closest_pose = path.points.at(object_closest_index).point.pose;

  lanelet::ConstLanelet closest_lanelet;
  if (!route_handler.getClosestLaneletWithinRoute(object_closest_pose, &closest_lanelet)) {
    return false;
  }

  const double lat_dist =
    autoware::motion_utils::calcLateralOffset(path.points, object_pose.position);
  const auto most_side_lanelet =
    lat_dist > 0.0 ? route_handler.getMostLeftLanelet(closest_lanelet, false, true)
                   : route_handler.getMostRightLanelet(closest_lanelet, false, true);
  const auto bound = lat_dist > 0.0 ? most_side_lanelet.leftBound2d().basicLineString()
                                    : most_side_lanelet.rightBound2d().basicLineString();
  const lanelet::Attribute lanelet_sub_type =
    most_side_lanelet.attribute(lanelet::AttributeName::Subtype);
  const auto center_to_bound_buffer =
    lanelet_sub_type.value() == "road_shoulder" ? 0.0 : object_check_min_road_shoulder_width;

  return isParkedObject(
    closest_lanelet, bound, object, center_to_bound_buffer, object_shiftable_ratio_threshold);
}

[[nodiscard]] size_t findNearestIndex(const T & points, const geometry_msgs::msg::Point & point)
{
  validateNonEmpty(points);

  double min_dist = std::numeric_limits<double>::max();
  size_t min_idx = 0;

  for (size_t i = 0; i < points.size(); ++i) {
    const auto dist = autoware_utils_geometry::calc_squared_distance2d(points.at(i), point);
    if (dist < min_dist) {
      min_dist = dist;
      min_idx = i;
    }
  }
  return min_idx;
}

double calc_squared_distance2d(const Point1 & point1, const Point2 & point2)
{
  const auto p1 = get_point(point1);
  const auto p2 = get_point(point2);
  const auto dx = p1.x - p2.x;
  const auto dy = p1.y - p2.y;
  return dx * dx + dy * dy;
}

geometry_msgs::msg::Point get_point(const T & p)
{
  return geometry_msgs::build<geometry_msgs::msg::Point>().x(p.x).y(p.y).z(p.z);
}

bool RouteHandler::getClosestLaneletWithinRoute(
  const Pose & search_pose, lanelet::ConstLanelet * closest_lanelet) const
{
  if (route_lanelets_.empty() || closest_lanelet == nullptr) {
    return false;
  }
  const auto search_point = lanelet::BasicPoint2d(search_pose.position.x, search_pose.position.y);
  const auto query_nearest = boost::geometry::index::nearest(search_point, route_lanelets_.size());
  auto min_dist_to_route_lanelet = std::numeric_limits<double>::max();
  size_t nearest_id = 0;
  // search starting from the nearest bounding box
  for (auto query_it = route_lanelets_rtree_.qbegin(query_nearest);
       query_it != route_lanelets_rtree_.qend(); ++query_it) {
    const auto dist_to_bbox = boost::geometry::comparable_distance(search_point, query_it->first);
    // stop when the distance to the bounding box is larger than the min distance found so far
    if (dist_to_bbox > min_dist_to_route_lanelet) {
      break;
    }
    const auto dist = boost::geometry::comparable_distance(
      search_point, route_lanelets_[query_it->second].polygon2d().basicPolygon());
    if (dist < min_dist_to_route_lanelet) {
      min_dist_to_route_lanelet = dist;
      nearest_id = query_it->second;
    }
  }
  *closest_lanelet = route_lanelets_[nearest_id];
  return true;
}

double calcLateralOffset(
  const T & points, const geometry_msgs::msg::Point & p_target, const bool throw_exception = false)
{
  const auto overlap_removed_points = removeOverlapPoints(points, 0);

  if (throw_exception) {
    validateNonEmpty(overlap_removed_points);
  } else {
    try {
      validateNonEmpty(overlap_removed_points);
    } catch (const std::exception & e) {
      RCLCPP_DEBUG(
        get_logger(),
        "%s Return NaN since no_throw option is enabled. The maintainer must check the code.",
        e.what());
      return std::nan("");
    }
  }

  if (overlap_removed_points.size() == 1) {
    const std::string error_message(
      "[autoware_motion_utils] " + std::string(__func__) +
      ": Lateral offset calculation is not supported for the same points.");
    autoware_utils_system::print_backtrace();
    if (throw_exception) {
      throw std::runtime_error(error_message);
    }
    RCLCPP_DEBUG(
      get_logger(),
      "%s Return NaN since no_throw option is enabled. The maintainer must check the code.",
      error_message.c_str());
    return std::nan("");
  }

  const size_t seg_idx = findNearestSegmentIndex(overlap_removed_points, p_target);
  return calcLateralOffset(points, p_target, seg_idx, throw_exception);
}

[[nodiscard]] T removeOverlapPoints(const T & points, const size_t start_idx = 0)
{
  if (points.size() < start_idx + 1) {
    return points;
  }

  T dst;
  dst.reserve(points.size());

  for (size_t i = 0; i <= start_idx; ++i) {
    dst.push_back(points.at(i));
  }

  constexpr double eps = 1.0E-08;
  for (size_t i = start_idx + 1; i < points.size(); ++i) {
    const auto prev_p = autoware_utils_geometry::get_point(dst.back());
    const auto curr_p = autoware_utils_geometry::get_point(points.at(i));
    if (std::abs(prev_p.x - curr_p.x) < eps && std::abs(prev_p.y - curr_p.y) < eps) {
      continue;
    }
    dst.push_back(points.at(i));
  }

  return dst;
}

geometry_msgs::msg::Point get_point(const T & p)
{
  return geometry_msgs::build<geometry_msgs::msg::Point>().x(p.x).y(p.y).z(p.z);
}

size_t findNearestSegmentIndex(const T & points, const geometry_msgs::msg::Point & point)
{
  const size_t nearest_idx = findNearestIndex(points, point);

  if (nearest_idx == 0) {
    return 0;
  }
  if (nearest_idx == points.size() - 1) {
    return points.size() - 2;
  }

  const double signed_length = calcLongitudinalOffsetToSegment(points, nearest_idx, point);

  if (signed_length <= 0) {
    return nearest_idx - 1;
  }

  return nearest_idx;
}

[[nodiscard]] size_t findNearestIndex(const T & points, const geometry_msgs::msg::Point & point)
{
  validateNonEmpty(points);

  double min_dist = std::numeric_limits<double>::max();
  size_t min_idx = 0;

  for (size_t i = 0; i < points.size(); ++i) {
    const auto dist = autoware_utils_geometry::calc_squared_distance2d(points.at(i), point);
    if (dist < min_dist) {
      min_dist = dist;
      min_idx = i;
    }
  }
  return min_idx;
}

double calc_squared_distance2d(const Point1 & point1, const Point2 & point2)
{
  const auto p1 = get_point(point1);
  const auto p2 = get_point(point2);
  const auto dx = p1.x - p2.x;
  const auto dy = p1.y - p2.y;
  return dx * dx + dy * dy;
}

