bool path_footprint_exceeds_target_lane_bound(
  const CommonDataPtr & common_data_ptr, const PathWithLaneId & path, const VehicleInfo & ego_info,
  const double margin)
{
  if (common_data_ptr->direction == Direction::NONE || path.points.empty()) {
    return false;
  }

  const auto & target_lanes = common_data_ptr->lanes_ptr->target;
  const bool is_left = common_data_ptr->direction == Direction::LEFT;

  const auto combined_target_lane_opt =
    autoware::experimental::lanelet2_utils::combine_lanelets_shape(target_lanes);
  if (!combined_target_lane_opt) {
    // empty target_lanes -> no boundary
    return false;
  }
  const auto & combined_target_lane = combined_target_lane_opt.value();

  for (const auto & path_point : path.points) {
    const auto & pose = path_point.point.pose;
    const auto front_vertex = getEgoFrontVertex(pose, ego_info, is_left);

    const auto sign = is_left ? -1.0 : 1.0;
    const auto dist_to_boundary =
      sign * utils::getSignedDistanceFromLaneBoundary(combined_target_lane, front_vertex, is_left);

    if (dist_to_boundary < margin) {
      RCLCPP_DEBUG(get_logger(), "Path footprint exceeds target lane boundary");
      return true;
    }
  }

  return false;
}

std::optional<lanelet::ConstLanelet> combine_lanelets_shape(const lanelet::ConstLanelets & lanelets)
{
  if (lanelets.empty()) {
    return std::nullopt;
  }
  const auto add_unique_point =
    [](lanelet::ConstPoints3d & points, const lanelet::ConstPoint3d & new_point) {
      constexpr double distance_threshold = 0.01;
      const auto is_duplicate = std::any_of(
        points.cbegin(), points.cend(),
        [&new_point, distance_threshold](const auto & existing_point) {
          return boost::geometry::distance(existing_point.basicPoint(), new_point.basicPoint()) <=
                 distance_threshold;
        });
      if (!is_duplicate) points.emplace_back(new_point);
    };

  const auto add_unique_points = [&add_unique_point](
                                   lanelet::ConstPoints3d & output, const auto & input_points) {
    std::for_each(
      input_points.begin(), input_points.end(),
      [&output, &add_unique_point](const auto & pt) { add_unique_point(output, pt); });
  };

  lanelet::ConstPoints3d lefts, rights, centers;
  for (const auto & llt : lanelets) {
    add_unique_points(lefts, llt.leftBound());
    add_unique_points(rights, llt.rightBound());
    add_unique_points(centers, llt.centerline());
  }

  const auto combined_lanelet_opt = create_safe_lanelet(lefts, rights);
  if (!combined_lanelet_opt.has_value()) {
    return std::nullopt;
  }
  auto combined_lanelet = remove_const(*combined_lanelet_opt);

  const auto center_line_opt = create_safe_linestring(centers);
  if (!center_line_opt.has_value()) {
    return std::nullopt;
  }
  const auto center_line = remove_const(*center_line_opt);

  combined_lanelet.setCenterline(center_line);
  return combined_lanelet;
}

std::optional<lanelet::ConstLanelet> create_safe_lanelet(
  const lanelet::ConstLineString3d & left_linestring,
  const lanelet::ConstLineString3d & right_linestring)
{
  if (left_linestring.size() < 2 || right_linestring.size() < 2) {
    return std::nullopt;
  }

  const auto left_ls = remove_const(left_linestring);
  const auto right_ls = remove_const(right_linestring);

  return lanelet::ConstLanelet{lanelet::InvalId, left_ls, right_ls};
}

lanelet::LineString3d remove_const(const lanelet::ConstLineString3d & const_linestring)
{
  return lanelet::LineString3d{
    std::const_pointer_cast<lanelet::LineStringData>(const_linestring.constData())};
}

lanelet::LineString3d remove_const(const lanelet::ConstLineString3d & const_linestring)
{
  return lanelet::LineString3d{
    std::const_pointer_cast<lanelet::LineStringData>(const_linestring.constData())};
}

Point getEgoFrontVertex(
  const Pose & ego_pose, const autoware::vehicle_info_utils::VehicleInfo & ego_info, bool left)
{
  const double lon_offset = ego_info.wheel_base_m + ego_info.front_overhang_m;
  const double lat_offset = 0.5 * (left ? ego_info.vehicle_width_m : -ego_info.vehicle_width_m);
  return autoware_utils::calc_offset_pose(ego_pose, lon_offset, lat_offset, 0.0).position;
}

geometry_msgs::msg::Pose calc_offset_pose(
  const geometry_msgs::msg::Pose & p, const double x, const double y, const double z,
  const double yaw)
{
  geometry_msgs::msg::Pose pose;
  geometry_msgs::msg::Transform transform;
  transform.translation = create_translation(x, y, z);
  transform.rotation = create_quaternion_from_yaw(yaw);
  tf2::Transform tf_pose;
  tf2::Transform tf_offset;
  tf2::fromMsg(transform, tf_offset);
  tf2::fromMsg(p, tf_pose);
  tf2::toMsg(tf_pose * tf_offset, pose);
  return pose;
}

geometry_msgs::msg::Vector3 create_translation(const double x, const double y, const double z)
{
  geometry_msgs::msg::Vector3 v;
  v.x = x;
  v.y = y;
  v.z = z;
  return v;
}

geometry_msgs::msg::Quaternion create_quaternion_from_yaw(const double yaw)
{
  tf2::Quaternion q;
  q.setRPY(0, 0, yaw);
  return tf2::toMsg(q);
}

double getSignedDistanceFromLaneBoundary(
  const lanelet::ConstLanelet & lanelet, const Point & position, bool left_side)
{
  const auto lanelet_point = experimental::lanelet2_utils::from_ros(position);
  const auto & boundary_line_2d = left_side ? lanelet.leftBound2d() : lanelet.rightBound2d();
  const auto arc_coordinates = lanelet::geometry::toArcCoordinates(
    boundary_line_2d, lanelet::utils::to2D(lanelet_point).basicPoint());
  return arc_coordinates.distance;
}

using autoware::experimental::lanelet2_utils::from_ros;
using autoware::experimental::lanelet2_utils::interpolate_point;
using autoware::experimental::lanelet2_utils::to_ros;
using lanelet::utils::to2D;

// 1. calculate reference points by lanelets' centerline
// NOTE: This vector aligns the vector lanelet_sequence.
std::vector<PiecewiseReferencePoints> piecewise_ref_points_vec;
for (const auto & llt : lanelet_sequence) {
  const lanelet::ConstLineString3d centerline = llt.centerline();

  piecewise_ref_points_vec.push_back(std::vector<ReferencePoint>{});
  for (const auto & center_point : centerline) {
    piecewise_ref_points_vec.back().push_back(
      ReferencePoint{false, experimental::lanelet2_utils::to_ros(center_point)});
  }
}

ArcCoordinates toArcCoordinates(const LineString2dT& lineString, const BasicPoint2d& point) {
  auto res = internal::signedDistanceImpl(lineString, point);
  auto dist = res.first;
  const auto& projectedPoint = res.second;
  // find first point in segment in linestring
  double length = 0.;
  auto accumulateLength = [&](const auto& first, const auto& second) {
    if (boost::geometry::equals(first, projectedPoint.closestSegment.first)) {
      return true;
    }
    length += distance(first, second);
    return false;
  };
  helper::forEachPairUntil(lineString.begin(), lineString.end(), accumulateLength);
  length += distance(projectedPoint.closestSegment.first, projectedPoint.projectedPoint);
  return {length, dist};
}

std::vector<std::vector<PoseWithVelocityStamped>> convert_to_predicted_paths(
  const CommonDataPtr & common_data_ptr, const LaneChangePath & lane_change_path,
  const size_t deceleration_sampling_num, const bool is_approved)
{
  static constexpr double floating_err_th{1e-3};
  const auto bpp_param = *common_data_ptr->bpp_param_ptr;
  const auto global_min_acc = bpp_param.min_acc;
  const auto lane_changing_acc = lane_change_path.info.longitudinal_acceleration.lane_changing;

  const auto min_acc = std::min(lane_changing_acc, global_min_acc);
  const auto sampling_num =
    std::abs(min_acc - lane_changing_acc) > floating_err_th ? deceleration_sampling_num : 1;
  const auto acc_resolution = (min_acc - lane_changing_acc) / static_cast<double>(sampling_num);

  const auto ego_predicted_path = [&](size_t n) {
    if (lane_change_path.type == PathType::FrenetPlanner) {
      return convert_to_predicted_path(
        common_data_ptr, lane_change_path.frenet_path, deceleration_sampling_num);
    }
    auto acc = lane_changing_acc + static_cast<double>(n) * acc_resolution;
    if (is_approved) {
      return utils::lane_change::convert_to_predicted_path(common_data_ptr, lane_change_path);
    }
    return utils::lane_change::convert_to_predicted_path(common_data_ptr, lane_change_path, acc);
  };

  return ranges::views::iota(0UL, sampling_num) | ranges::views::transform(ego_predicted_path) |
         ranges::to<std::vector>();
}

std::vector<PoseWithVelocityStamped> convert_to_predicted_path(
  const CommonDataPtr & common_data_ptr, const LaneChangePath & lane_change_path,
  const double lane_changing_acceleration)
{
  if (lane_change_path.path.points.empty()) {
    return {};
  }

  const auto & path = lane_change_path.path;
  const auto & vehicle_pose = common_data_ptr->get_ego_pose();
  const auto & bpp_param_ptr = common_data_ptr->bpp_param_ptr;
  const auto ego_arc_length = calc_arc_length(path.points, vehicle_pose, *bpp_param_ptr);

  const auto initial_velocity = common_data_ptr->get_ego_speed();
  const auto prepare_acc = lane_change_path.info.longitudinal_acceleration.prepare;
  const auto duration = lane_change_path.info.duration.sum();
  const auto prepare_time = lane_change_path.info.duration.prepare;
  const auto & lc_param_ptr = common_data_ptr->lc_param_ptr;
  const auto resolution = lc_param_ptr->safety.collision_check.prediction_time_resolution;
  std::vector<PoseWithVelocityStamped> predicted_path;
  predicted_path.reserve(static_cast<size_t>(std::ceil(duration / resolution)));

  // prepare segment
  for (double t = 0.0; t < prepare_time; t += resolution) {
    const auto velocity =
      std::clamp(initial_velocity + prepare_acc * t, 0.0, lane_change_path.info.velocity.prepare);
    const auto length = initial_velocity * t + 0.5 * prepare_acc * t * t;
    const auto pose =
      autoware::motion_utils::calcInterpolatedPose(path.points, ego_arc_length + length);
    predicted_path.emplace_back(t, pose, velocity);
  }

  // lane changing segment
  const auto lane_changing_velocity = std::clamp(
    initial_velocity + prepare_acc * prepare_time, 0.0, lane_change_path.info.velocity.prepare);
  const auto offset =
    initial_velocity * prepare_time + 0.5 * prepare_acc * prepare_time * prepare_time;

  for (double t = prepare_time; t < duration; t += resolution) {
    const auto delta_t = t - prepare_time;
    const auto velocity = std::clamp(
      lane_changing_velocity + lane_changing_acceleration * delta_t, 0.0,
      lane_change_path.info.velocity.lane_changing);
    const auto length = lane_changing_velocity * delta_t +
                        0.5 * lane_changing_acceleration * delta_t * delta_t + offset;
    const auto pose =
      autoware::motion_utils::calcInterpolatedPose(path.points, ego_arc_length + length);

    predicted_path.emplace_back(t, pose, velocity);
  }

  return predicted_path;
}

double calc_arc_length(
  const T & reference_path, const geometry_msgs::msg::Pose & pose,
  const BehaviorPathPlannerParameters & bpp_params)
{
  if (reference_path.empty()) {
    return 0.0;
  }
  const auto nearest_seg_idx =
    autoware::motion_utils::findFirstNearestSegmentIndexWithSoftConstraints(
      reference_path, pose, bpp_params.ego_nearest_dist_threshold,
      bpp_params.ego_nearest_yaw_threshold);

  auto frenet_point = autoware::behavior_path_planner::utils::convertToFrenetPoint(
    reference_path, pose.position, nearest_seg_idx);
  return frenet_point.length;
}

size_t findFirstNearestSegmentIndexWithSoftConstraints(
  const T & points, const geometry_msgs::msg::Pose & pose,
  const double dist_threshold = std::numeric_limits<double>::max(),
  const double yaw_threshold = std::numeric_limits<double>::max())
{
  // find first nearest index with soft constraints (not segment index)
  const size_t nearest_idx =
    findFirstNearestIndexWithSoftConstraints(points, pose, dist_threshold, yaw_threshold);

  // calculate segment index
  if (nearest_idx == 0) {
    return 0;
  }
  if (nearest_idx == points.size() - 1) {
    return points.size() - 2;
  }

  const double signed_length = calcLongitudinalOffsetToSegment(points, nearest_idx, pose.position);

  if (signed_length <= 0) {
    return nearest_idx - 1;
  }

  return nearest_idx;
}

size_t findFirstNearestIndexWithSoftConstraints(
  const T & points, const geometry_msgs::msg::Pose & pose,
  const double dist_threshold = std::numeric_limits<double>::max(),
  const double yaw_threshold = std::numeric_limits<double>::max())
{
  validateNonEmpty(points);

  {  // with dist and yaw thresholds
    const double squared_dist_threshold = dist_threshold * dist_threshold;
    double min_squared_dist = std::numeric_limits<double>::max();
    size_t min_idx = 0;
    bool is_within_constraints = false;
    for (size_t i = 0; i < points.size(); ++i) {
      const auto squared_dist =
        autoware_utils_geometry::calc_squared_distance2d(points.at(i), pose.position);
      const auto yaw = autoware_utils_geometry::calc_yaw_deviation(
        autoware_utils_geometry::get_pose(points.at(i)), pose);

      if (squared_dist_threshold < squared_dist || yaw_threshold < std::abs(yaw)) {
        if (is_within_constraints) {
          break;
        }
        continue;
      }

      if (min_squared_dist <= squared_dist) {
        continue;
      }

      min_squared_dist = squared_dist;
      min_idx = i;
      is_within_constraints = true;
    }

    // nearest index is found
    if (is_within_constraints) {
      return min_idx;
    }
  }

  {  // with dist threshold
    const double squared_dist_threshold = dist_threshold * dist_threshold;
    double min_squared_dist = std::numeric_limits<double>::max();
    size_t min_idx = 0;
    bool is_within_constraints = false;
    for (size_t i = 0; i < points.size(); ++i) {
      const auto squared_dist =
        autoware_utils_geometry::calc_squared_distance2d(points.at(i), pose.position);

      if (squared_dist_threshold < squared_dist) {
        if (is_within_constraints) {
          break;
        }
        continue;
      }

      if (min_squared_dist <= squared_dist) {
        continue;
      }

      min_squared_dist = squared_dist;
      min_idx = i;
      is_within_constraints = true;
    }

    // nearest index is found
    if (is_within_constraints) {
      return min_idx;
    }
  }

  {  // with yaw threshold
    double min_squared_dist = std::numeric_limits<double>::max();
    size_t min_idx = 0;
    bool is_within_constraints = false;
    for (size_t i = 0; i < points.size(); ++i) {
      const auto yaw = autoware_utils_geometry::calc_yaw_deviation(
        autoware_utils_geometry::get_pose(points.at(i)), pose);

      if (yaw_threshold < std::abs(yaw)) {
        if (is_within_constraints) {
          break;
        }
        continue;
      }

      const auto squared_dist =
        autoware_utils_geometry::calc_squared_distance2d(points.at(i), pose.position);
      if (min_squared_dist <= squared_dist) {
        continue;
      }

      min_squared_dist = squared_dist;
      min_idx = i;
      is_within_constraints = true;
    }

    // nearest index is found
    if (is_within_constraints) {
      return min_idx;
    }
  }

  // without any threshold
  return findNearestIndex(points, pose.position);
}

double calc_squared_distance2d(const Point1 & point1, const Point2 & point2)
{
  const auto p1 = get_point(point1);
  const auto p2 = get_point(point2);
  const auto dx = p1.x - p2.x;
  const auto dy = p1.y - p2.y;
  return dx * dx + dy * dy;
}

geometry_msgs::msg::Point get_point(const T & p)
{
  return geometry_msgs::build<geometry_msgs::msg::Point>().x(p.x).y(p.y).z(p.z);
}

double calc_yaw_deviation(
