double calc_elevation_angle(
  const geometry_msgs::msg::Point & p_from, const geometry_msgs::msg::Point & p_to)
{
  const double dz = p_to.z - p_from.z;
  const double dist_2d = calc_distance2d(p_from, p_to);
  return std::atan2(dz, dist_2d);
}

double calc_distance2d(const Point1 & point1, const Point2 & point2)
{
  const auto p1 = get_point(point1);
  const auto p2 = get_point(point2);
  return std::hypot(p1.x - p2.x, p1.y - p2.y);
}

geometry_msgs::msg::Point get_point(const T & p)
{
  return geometry_msgs::build<geometry_msgs::msg::Point>().x(p.x).y(p.y).z(p.z);
}

double calc_azimuth_angle(
  const geometry_msgs::msg::Point & p_from, const geometry_msgs::msg::Point & p_to)
{
  const double dx = p_to.x - p_from.x;
  const double dy = p_to.y - p_from.y;
  return std::atan2(dy, dx);
}

PathSafetyStatus NormalLaneChange::isLaneChangePathSafe(
  const LaneChangePath & lane_change_path,
  const std::vector<std::vector<PoseWithVelocityStamped>> & ego_predicted_paths,
  const lane_change::TargetObjects & collision_check_objects,
  const utils::path_safety_checker::RSSparams & rss_params, CollisionCheckDebugMap & debug_data,
  const bool is_approved) const
{
  autoware_utils::ScopedTimeTrack st(__func__, *time_keeper_);
  constexpr auto is_safe = true;
  constexpr auto is_moving_object_behind_ego = true;
  if (ego_predicted_paths.empty()) {
    return {is_safe, !is_moving_object_behind_ego};
  }

  const auto check_for_colliding_objects =
    [&](decltype(ego_predicted_paths) & ego_pred_paths, const auto & objects) {
      return find_colliding_object_if_all_paths_collide(
        lane_change_path, ego_pred_paths, objects, rss_params, debug_data, is_approved);
    };

  const auto check_for_moving_objects = [this](const auto & object) {
    return utils::lane_change::is_moving_object(common_data_ptr_, object);
  };

  if (
    const auto found_colliding_objects_opt = check_for_colliding_objects(
      {ego_predicted_paths.front()}, collision_check_objects.trailing)) {
    const auto is_moving_object =
      ranges::any_of(*found_colliding_objects_opt, check_for_moving_objects);
    return {!is_safe, is_moving_object};
  }

  if (check_for_colliding_objects(ego_predicted_paths, collision_check_objects.leading)) {
    return {!is_safe, !is_moving_object_behind_ego};
  }

  return {is_safe, !is_moving_object_behind_ego};
}

NormalLaneChange::find_colliding_object_if_all_paths_collide(
  const LaneChangePath & lane_change_path,
  const std::vector<std::vector<PoseWithVelocityStamped>> & ego_predicted_paths,
  const ExtendedPredictedObjects & objects,
  const utils::path_safety_checker::RSSparams & rss_params, CollisionCheckDebugMap & debug_data,
  const bool is_approved) const
{
  std::vector<ExtendedPredictedObject> colliding_objects;
  std::unordered_set<size_t> objects_idx;

  const auto check_for_collision = [&](const auto & ego_predicted_path, const auto & object) {
    return is_colliding(
      lane_change_path, object, ego_predicted_path, rss_params, debug_data, is_approved);
  };

  const auto check_for_collisions = [&](const auto & ego_predicted_path) {
    std::vector<ExtendedPredictedObject> current_colliding_objects;
    current_colliding_objects.reserve(objects.size());

    for (const auto & [idx, object] : objects | ranges::views::enumerate) {
      const auto is_colliding_object = check_for_collision(ego_predicted_path, object);
      if (!is_colliding_object) {
        continue;
      }
      if (objects_idx.find(idx) == objects_idx.end()) {
        current_colliding_objects.push_back(object);
        objects_idx.insert(idx);
      }
    }

    if (current_colliding_objects.empty()) {
      return false;
    }

    std::move(
      current_colliding_objects.begin(), current_colliding_objects.end(),
      std::back_inserter(colliding_objects));

    return true;
  };

  if (ranges::all_of(ego_predicted_paths, check_for_collisions)) {
    return colliding_objects;
  }

  return std::nullopt;
}

bool NormalLaneChange::is_colliding(
  const LaneChangePath & lane_change_path, const ExtendedPredictedObject & obj,
  const std::vector<PoseWithVelocityStamped> & ego_predicted_path, const RSSparams & rss_param,
  CollisionCheckDebugMap & debug_data, const bool is_approved) const
{
  constexpr auto is_colliding{true};

  if (lane_change_path.path.points.empty()) {
    return !is_colliding;
  }

  if (ego_predicted_path.empty()) {
    return !is_colliding;
  }

  const auto & lanes_polygon_ptr = common_data_ptr_->lanes_polygon_ptr;
  const auto & current_polygon = lanes_polygon_ptr->current;
  const auto & expanded_target_polygon = lanes_polygon_ptr->target;

  if (current_polygon.empty() || expanded_target_polygon.empty()) {
    return !is_colliding;
  }

  constexpr auto is_safe{true};
  auto current_debug_data = utils::path_safety_checker::createObjectDebug(obj);
  constexpr auto hysteresis_factor{1.0};
  const auto safety_check_max_vel = get_max_velocity_for_safety_check();
  const auto & bpp_param = *common_data_ptr_->bpp_param_ptr;
  const auto th_yaw_diff = common_data_ptr_->lc_param_ptr->safety.collision_check.th_yaw_diff;
  const auto prepare_duration = lane_change_path.info.duration.prepare;

  auto & debug = current_debug_data.second;
  debug.ego_predicted_path = ego_predicted_path;
  debug.current_obj_pose = obj.initial_pose;

  const auto & th_stopped_obj_vel = lane_change_parameters_->safety.th_stopped_object_velocity;
  const auto & lane_changing_phase_rss_param =
    (!is_approved && obj.initial_twist.linear.x <= th_stopped_obj_vel)
      ? lane_change_parameters_->safety.rss_params_for_parked
      : rss_param;

  for (const auto & obj_path : obj.predicted_paths) {
    debug.obj_predicted_path = obj_path.path;

    std::vector<autoware_utils_geometry::Polygon2d> collided_polygons{};
    collided_polygons.reserve(obj_path.path.size());
    for (const auto & obj_pose_with_poly : obj_path.path) {
      CollisionCheckDebug * debug_ptr = collided_polygons.empty() ? &debug : nullptr;
      const auto & selected_rss_param =
        obj_pose_with_poly.time < prepare_duration
          ? common_data_ptr_->lc_param_ptr->safety.rss_params_for_prepare
          : lane_changing_phase_rss_param;

      if (
        const auto collided_polygon_opt = check_collision(
          lane_change_path.path, bpp_param.vehicle_info, ego_predicted_path, obj_pose_with_poly,
          selected_rss_param, th_yaw_diff, safety_check_max_vel, hysteresis_factor, debug_ptr)) {
        collided_polygons.push_back(*collided_polygon_opt);
      }
    }

    if (collided_polygons.empty()) {
      utils::path_safety_checker::updateCollisionCheckDebugMap(
        debug_data, current_debug_data, is_safe);
      continue;
    }

    const auto collision_in_current_lanes =
      utils::lane_change::is_collided_polygons_in_lanelet(collided_polygons, current_polygon);
    const auto collision_in_target_lanes = utils::lane_change::is_collided_polygons_in_lanelet(
      collided_polygons, expanded_target_polygon);

    if (!collision_in_current_lanes && !collision_in_target_lanes) {
      utils::path_safety_checker::updateCollisionCheckDebugMap(
        debug_data, current_debug_data, is_safe);
      continue;
    }

    utils::path_safety_checker::updateCollisionCheckDebugMap(
      debug_data, current_debug_data, !is_safe);
    return is_colliding;
  }
  utils::path_safety_checker::updateCollisionCheckDebugMap(debug_data, current_debug_data, is_safe);
  return !is_colliding;
}

double NormalLaneChange::get_max_velocity_for_safety_check() const
{
  autoware_utils::ScopedTimeTrack st(__func__, *time_keeper_);
  const auto external_velocity_limit_ptr = planner_data_->external_limit_max_velocity;
  if (external_velocity_limit_ptr) {
    return std::min(
      static_cast<double>(external_velocity_limit_ptr->max_velocity), getCommonParam().max_vel);
  }

  return getCommonParam().max_vel;
}

CollisionCheckDebugPair createObjectDebug(const ExtendedPredictedObject & obj)
{
  CollisionCheckDebug debug;
  debug.current_obj_pose = obj.initial_pose;
  debug.extended_obj_polygon = autoware_utils::to_polygon2d(obj.initial_pose, obj.shape);
  debug.obj_shape = obj.shape;
  debug.current_twist = obj.initial_twist;
  return {autoware_utils::to_boost_uuid(obj.uuid), debug};
}

Polygon2d to_polygon2d(
  const geometry_msgs::msg::Pose & pose, const autoware_perception_msgs::msg::Shape & shape)
{
  Polygon2d polygon;

  if (shape.type == autoware_perception_msgs::msg::Shape::BOUNDING_BOX) {
    const auto point0 = autoware_utils_geometry::calc_offset_pose(
                          pose, shape.dimensions.x / 2.0, shape.dimensions.y / 2.0, 0.0)
                          .position;
    const auto point1 = autoware_utils_geometry::calc_offset_pose(
                          pose, -shape.dimensions.x / 2.0, shape.dimensions.y / 2.0, 0.0)
                          .position;
    const auto point2 = autoware_utils_geometry::calc_offset_pose(
                          pose, -shape.dimensions.x / 2.0, -shape.dimensions.y / 2.0, 0.0)
                          .position;
    const auto point3 = autoware_utils_geometry::calc_offset_pose(
                          pose, shape.dimensions.x / 2.0, -shape.dimensions.y / 2.0, 0.0)
                          .position;

    append_point_to_polygon(polygon, point0);
    append_point_to_polygon(polygon, point1);
    append_point_to_polygon(polygon, point2);
    append_point_to_polygon(polygon, point3);
  } else if (shape.type == autoware_perception_msgs::msg::Shape::CYLINDER) {
    const double radius = shape.dimensions.x / 2.0;
    constexpr int circle_discrete_num = 6;
    for (int i = 0; i < circle_discrete_num; ++i) {
      geometry_msgs::msg::Point point;
      point.x = std::cos(
                  (static_cast<double>(i) / static_cast<double>(circle_discrete_num)) * 2.0 * M_PI +
                  M_PI / static_cast<double>(circle_discrete_num)) *
                  radius +
                pose.position.x;
      point.y = std::sin(
                  (static_cast<double>(i) / static_cast<double>(circle_discrete_num)) * 2.0 * M_PI +
                  M_PI / static_cast<double>(circle_discrete_num)) *
                  radius +
                pose.position.y;
      append_point_to_polygon(polygon, point);
    }
  } else if (shape.type == autoware_perception_msgs::msg::Shape::POLYGON) {
    const double poly_yaw = tf2::getYaw(pose.orientation);
    const auto rotated_footprint = rotate_polygon(shape.footprint, poly_yaw);
    for (const auto rel_point : rotated_footprint.points) {
      geometry_msgs::msg::Point abs_point;
      abs_point.x = pose.position.x + rel_point.x;
      abs_point.y = pose.position.y + rel_point.y;

      append_point_to_polygon(polygon, abs_point);
    }
  } else {
    throw std::logic_error("The shape type is not supported in autoware_utils.");
  }

  // NOTE: push back the first point in order to close polygon
  if (!polygon.outer().empty()) {
    append_point_to_polygon(polygon, polygon.outer().front());
  }

  return is_clockwise(polygon) ? polygon : inverse_clockwise(polygon);
}

  using autoware_utils_geometry::calc_offset_pose;
  Polygon2d polygon;
  const auto point0 = calc_offset_pose(base_link_pose, base_to_front, width / 2.0, 0.0).position;
  const auto point1 = calc_offset_pose(base_link_pose, base_to_front, -width / 2.0, 0.0).position;
  const auto point2 = calc_offset_pose(base_link_pose, -base_to_rear, -width / 2.0, 0.0).position;
  const auto point3 = calc_offset_pose(base_link_pose, -base_to_rear, width / 2.0, 0.0).position;

  append_point_to_polygon(polygon, point0);
  append_point_to_polygon(polygon, point1);
  append_point_to_polygon(polygon, point2);
  append_point_to_polygon(polygon, point3);
  append_point_to_polygon(polygon, point0);

  return is_clockwise(polygon) ? polygon : inverse_clockwise(polygon);
}

double get_area(const autoware_perception_msgs::msg::Shape & shape)
{
  if (shape.type == autoware_perception_msgs::msg::Shape::BOUNDING_BOX) {
    return get_rectangle_area(shape.dimensions);
  } else if (shape.type == autoware_perception_msgs::msg::Shape::CYLINDER) {
    return get_circle_area(shape.dimensions);
  } else if (shape.type == autoware_perception_msgs::msg::Shape::POLYGON) {
    return get_polygon_area(shape.footprint);
  }

  throw std::logic_error("The shape type is not supported in autoware_utils.");
}

geometry_msgs::msg::Polygon rotate_polygon(
  const geometry_msgs::msg::Polygon & polygon, const double & angle)
{
  const double cos = std::cos(angle);
  const double sin = std::sin(angle);
  geometry_msgs::msg::Polygon rotated_polygon;
  for (const auto & point : polygon.points) {
    auto rotated_point = point;
    rotated_point.x = cos * point.x - sin * point.y;
    rotated_point.y = sin * point.x + cos * point.y;
    rotated_polygon.points.push_back(rotated_point);
  }
  return rotated_polygon;
}

void append_point_to_polygon(Polygon2d & polygon, const geometry_msgs::msg::Point & geom_point)
{
  Point2d point;
  point.x() = geom_point.x;
  point.y() = geom_point.y;

  bg::append(polygon.outer(), point);
}

void append_point_to_polygon(Polygon2d & polygon, const geometry_msgs::msg::Point & geom_point)
{
  Point2d point;
  point.x() = geom_point.x;
  point.y() = geom_point.y;

  bg::append(polygon.outer(), point);
}

bool is_clockwise(const Polygon2d & polygon)
{
  const int n = polygon.outer().size();
  const double x_offset = polygon.outer().at(0).x();
  const double y_offset = polygon.outer().at(0).y();
  double sum = 0.0;
  for (std::size_t i = 0; i < polygon.outer().size(); ++i) {
    sum +=
      (polygon.outer().at(i).x() - x_offset) * (polygon.outer().at((i + 1) % n).y() - y_offset) -
      (polygon.outer().at(i).y() - y_offset) * (polygon.outer().at((i + 1) % n).x() - x_offset);
  }

  return sum < 0.0;
}

inline boost::uuids::uuid to_boost_uuid(const unique_identifier_msgs::msg::UUID & id)
{
  boost::uuids::uuid boost_uuid{};
  std::copy(id.uuid.begin(), id.uuid.end(), boost_uuid.begin());
  return boost_uuid;
}

std::optional<Polygon2d> check_collision(
  const PathWithLaneId & planned_path, const VehicleInfo & vehicle_info,
  const std::vector<PoseWithVelocityStamped> & predicted_ego_path,
  const PoseWithVelocityAndPolygonStamped & obj_pose_with_poly, const RSSparams & rss_parameters,
  const double yaw_difference_th, const double max_velocity_limit, const double hysteresis_factor,
  CollisionCheckDebug * debug)
{
  const auto & current_time = obj_pose_with_poly.time;
  const auto & obj_pose = obj_pose_with_poly.pose;
  const auto & obj_polygon = obj_pose_with_poly.poly;

  // get ego information at current time
  // Note: we can create these polygons in advance. However, it can decrease the readability and
  // variability
  const auto & ego_vehicle_info = vehicle_info;
  const auto interpolated_data = get_interpolated_pose_with_velocity_and_polygon_stamped(
    predicted_ego_path, current_time, ego_vehicle_info);

  if (!interpolated_data) {
    return std::nullopt;
  }

  const auto & ego_pose = interpolated_data->pose;
  const auto & ego_polygon = interpolated_data->poly;

  if (is_yaw_diff_within_threshold(ego_pose, obj_pose, yaw_difference_th)) {
    return std::nullopt;
  }

  if (boost::geometry::intersects(ego_polygon, obj_polygon)) {
    if (debug) {
      debug->unsafe_reason = "overlap_polygon";
      debug->expected_ego_pose = ego_pose;
      debug->expected_obj_pose = obj_pose;
      debug->extended_ego_polygon = ego_polygon;
      debug->extended_obj_polygon = obj_polygon;
    }
    return obj_polygon;
  }

  const auto is_object_front =
    isTargetObjectFront(ego_pose, obj_polygon, ego_vehicle_info.max_longitudinal_offset_m);

  const auto ego_velocity = std::min(interpolated_data->velocity, max_velocity_limit);
  const auto object_velocity = obj_pose_with_poly.velocity;
  const auto & [front_object_velocity, rear_object_velocity] =
    is_object_front ? std::pair{object_velocity, ego_velocity}
                    : std::pair{ego_velocity, object_velocity};

  const auto rss_dist =
    calcRssDistance(front_object_velocity, rear_object_velocity, rss_parameters);

  const auto min_lon_length =
    calc_minimum_longitudinal_length(front_object_velocity, rear_object_velocity, rss_parameters);

  const auto lon_offset = std::max(rss_dist, min_lon_length) * hysteresis_factor;
  const auto lat_margin = rss_parameters.lateral_distance_max_threshold * hysteresis_factor;
  const auto is_stopping_object = object_velocity < 0.3;

  const auto extended_ego_polygon_opt = extend_ego_polygon(
    planned_path, ego_pose, ego_polygon, vehicle_info, lon_offset, lat_margin, rss_parameters,
    is_object_front, is_stopping_object, debug);

  if (!extended_ego_polygon_opt) {
    return std::nullopt;
  }

  const auto & extended_obj_polygon =
    is_object_front ? obj_polygon
                    : createExtendedPolygon(
                        obj_pose_with_poly, lon_offset, lat_margin, is_stopping_object, debug);

  // check intersects with extended polygon
  if (!boost::geometry::intersects(*extended_ego_polygon_opt, extended_obj_polygon)) {
    return std::nullopt;
  }

  if (debug) {
    debug->unsafe_reason = "overlap_extended_polygon";
    debug->rss_longitudinal = rss_dist;
    debug->inter_vehicle_distance = min_lon_length;
    debug->expected_ego_pose = ego_pose;
    debug->expected_obj_pose = obj_pose;
    debug->extended_ego_polygon = *extended_ego_polygon_opt;
    debug->extended_obj_polygon = extended_obj_polygon;
    debug->is_front = is_object_front;
  }
  return obj_polygon;
}

get_interpolated_pose_with_velocity_and_polygon_stamped(
  const std::vector<PoseWithVelocityStamped> & pred_path, const double current_time,
  const VehicleInfo & ego_info)
{
  const auto interpolation_result = calc_interpolated_pose_with_velocity(pred_path, current_time);

  if (!interpolation_result) {
    return {};
  }

  const auto & i = ego_info;
  const auto & base_to_front = i.max_longitudinal_offset_m;
  const auto & base_to_rear = i.rear_overhang_m;
  const auto & width = i.vehicle_width_m;
  const auto & pose = interpolation_result->pose;
  const auto & velocity = interpolation_result->velocity;

  const auto ego_polygon = autoware_utils::to_footprint(pose, base_to_front, base_to_rear, width);

  return PoseWithVelocityAndPolygonStamped{current_time, pose, velocity, ego_polygon};
}

std::optional<PoseWithVelocityStamped> calc_interpolated_pose_with_velocity(
  const std::vector<PoseWithVelocityStamped> & path, const double relative_time)
{
  // Check if relative time is in the valid range
  if (path.empty() || relative_time < 0.0) {
    return std::nullopt;
  }

  constexpr double epsilon = 1e-6;
  for (size_t path_idx = 1; path_idx < path.size(); ++path_idx) {
    const auto & pt = path.at(path_idx);
    const auto & prev_pt = path.at(path_idx - 1);
    if (relative_time < pt.time + epsilon) {
      const double offset = relative_time - prev_pt.time;
      const double time_step = pt.time - prev_pt.time;
      const double ratio = std::clamp(offset / time_step, 0.0, 1.0);
      const auto interpolated_pose =
        autoware_utils::calc_interpolated_pose(prev_pt.pose, pt.pose, ratio, false);
      const double interpolated_velocity =
        autoware::interpolation::lerp(prev_pt.velocity, pt.velocity, ratio);
      return PoseWithVelocityStamped{relative_time, interpolated_pose, interpolated_velocity};
    }
  }

  return std::nullopt;
}

geometry_msgs::msg::Pose calc_interpolated_pose(
  const Pose1 & src_pose, const Pose2 & dst_pose, const double ratio,
  const bool set_orientation_from_position_direction = true)
{
  const double clamped_ratio = std::clamp(ratio, 0.0, 1.0);

  geometry_msgs::msg::Pose output_pose;
  output_pose.position =
    calc_interpolated_point(get_point(src_pose), get_point(dst_pose), clamped_ratio);

  if (set_orientation_from_position_direction) {
    const double input_poses_dist = calc_distance2d(get_point(src_pose), get_point(dst_pose));
    const bool is_driving_forward_flag = is_driving_forward(src_pose, dst_pose);

    // Get orientation from interpolated point and src_pose
    if ((is_driving_forward_flag && clamped_ratio > 1.0 - (1e-6)) || input_poses_dist < 1e-3) {
      output_pose.orientation = get_pose(dst_pose).orientation;
    } else if (!is_driving_forward_flag && clamped_ratio < 1e-6) {
      output_pose.orientation = get_pose(src_pose).orientation;
    } else {
      const auto & base_pose = is_driving_forward_flag ? dst_pose : src_pose;
      const double pitch = calc_elevation_angle(get_point(output_pose), get_point(base_pose));
      const double yaw = calc_azimuth_angle(get_point(output_pose), get_point(base_pose));
      output_pose.orientation = create_quaternion_from_rpy(0.0, pitch, yaw);
    }
  } else {
    // Get orientation by spherical linear interpolation
    tf2::Transform src_tf;
    tf2::Transform dst_tf;
    tf2::fromMsg(get_pose(src_pose), src_tf);
    tf2::fromMsg(get_pose(dst_pose), dst_tf);
    const auto & quaternion = tf2::slerp(src_tf.getRotation(), dst_tf.getRotation(), clamped_ratio);
    output_pose.orientation = tf2::toMsg(quaternion);
  }

  return output_pose;
}

geometry_msgs::msg::Point calc_interpolated_point(
  const Point1 & src, const Point2 & dst, const double ratio)
{
  const auto src_point = get_point(src);
  const auto dst_point = get_point(dst);

  tf2::Vector3 src_vec;
  src_vec.setX(src_point.x);
  src_vec.setY(src_point.y);
  src_vec.setZ(src_point.z);

  tf2::Vector3 dst_vec;
  dst_vec.setX(dst_point.x);
  dst_vec.setY(dst_point.y);
  dst_vec.setZ(dst_point.z);

  // Get pose by linear interpolation
  const double clamped_ratio = std::clamp(ratio, 0.0, 1.0);
  const auto & vec = tf2::lerp(src_vec, dst_vec, clamped_ratio);

  geometry_msgs::msg::Point point;
  point.x = vec.x();
  point.y = vec.y();
  point.z = vec.z();

  return point;
}

geometry_msgs::msg::Point get_point(const T & p)
{
  return geometry_msgs::build<geometry_msgs::msg::Point>().x(p.x).y(p.y).z(p.z);
}

geometry_msgs::msg::Point get_point(const T & p)
{
  return geometry_msgs::build<geometry_msgs::msg::Point>().x(p.x).y(p.y).z(p.z);
}

double calc_distance2d(const Point1 & point1, const Point2 & point2)
{
  const auto p1 = get_point(point1);
  const auto p2 = get_point(point2);
  return std::hypot(p1.x - p2.x, p1.y - p2.y);
}

geometry_msgs::msg::Point get_point(const T & p)
{
  return geometry_msgs::build<geometry_msgs::msg::Point>().x(p.x).y(p.y).z(p.z);
}

bool is_driving_forward(const Pose1 & src_pose, const Pose2 & dst_pose)
{
  // check the first point direction
  const double src_yaw = tf2::getYaw(get_pose(src_pose).orientation);
  const double pose_direction_yaw = calc_azimuth_angle(get_point(src_pose), get_point(dst_pose));
  return std::fabs(normalize_radian(src_yaw - pose_direction_yaw)) < pi / 2.0;
}

geometry_msgs::msg::Pose get_pose([[maybe_unused]] const T & p)
{
  static_assert(sizeof(T) == 0, "Only specializations of get_pose can be used.");
  throw std::logic_error("Only specializations of get_pose can be used.");
}

double calc_azimuth_angle(
  const geometry_msgs::msg::Point & p_from, const geometry_msgs::msg::Point & p_to)
{
  const double dx = p_to.x - p_from.x;
  const double dy = p_to.y - p_from.y;
  return std::atan2(dy, dx);
}

inline double normalize_radian(const double rad, const double min_rad = -pi)
{
  const auto max_rad = min_rad + 2 * pi;

  const auto value = std::fmod(rad, 2 * pi);
  if (min_rad <= value && value < max_rad) {
    return value;
  }

  return value - std::copysign(2 * pi, value);
}

geometry_msgs::msg::Pose get_pose([[maybe_unused]] const T & p)
{
  static_assert(sizeof(T) == 0, "Only specializations of get_pose can be used.");
  throw std::logic_error("Only specializations of get_pose can be used.");
}

double calc_elevation_angle(
  const geometry_msgs::msg::Point & p_from, const geometry_msgs::msg::Point & p_to)
{
  const double dz = p_to.z - p_from.z;
  const double dist_2d = calc_distance2d(p_from, p_to);
  return std::atan2(dz, dist_2d);
}

double calc_distance2d(const Point1 & point1, const Point2 & point2)
{
  const auto p1 = get_point(point1);
  const auto p2 = get_point(point2);
  return std::hypot(p1.x - p2.x, p1.y - p2.y);
}

geometry_msgs::msg::Point get_point(const T & p)
{
  return geometry_msgs::build<geometry_msgs::msg::Point>().x(p.x).y(p.y).z(p.z);
}

double calc_azimuth_angle(
  const geometry_msgs::msg::Point & p_from, const geometry_msgs::msg::Point & p_to)
{
  const double dx = p_to.x - p_from.x;
  const double dy = p_to.y - p_from.y;
  return std::atan2(dy, dx);
}

bool is_moving_object(const CommonDataPtr & common_data_ptr, const ExtendedPredictedObject & object)
{
  return object.initial_twist.linear.x >
         common_data_ptr->lc_param_ptr->safety.th_stopped_object_velocity;
}

const auto check_for_colliding_objects =
  [&](decltype(ego_predicted_paths) & ego_pred_paths, const auto & objects) {
    return find_colliding_object_if_all_paths_collide(
      lane_change_path, ego_pred_paths, objects, rss_params, debug_data, is_approved);
  };
